// chiamata in vari punti, in modo  che siano diversi thread
// cerca di liberare la memoria per cui c'e' una richiesta di free
// che sia dello stesso thread attuale
// nota: se IdPrenotazione e' diverso da -1 allora fingera' che sia questo valore l'id attuale
void AllFreeMine(int IdPrenotazione)
{
	int Id;
	int i;
	void *pMem;
	bool TestCompatta;
	int j;

	if (IdPrenotazione != -1) {
		Id= IdPrenotazione;
	}else {

		Id=GetCurrentThreadId();
	}
	TestCompatta=false;

	for (i=0;i<BaseAlloc.TotAllocata;i++) {
		if (BaseAlloc.VetAllocata[i].TestFree ==1 && BaseAlloc.VetAllocata[i].pBaseMem != NULL && 
			BaseAlloc.VetAllocata[i].ThreadId == Id) {
			// ok, liberarla
			pMem= BaseAlloc.VetAllocata[i].pBaseMem;

			if (FreeMine(pMem)==true) {

				BaseAlloc.VetAllocata[i].pBaseMem=NULL;
				TestCompatta=true;
			}
		}
	}

	if (TestCompatta) {
		// e' stato fatto un campio: compattare il vettore in modo che non ci siano spazi vuoti
		j=0;
		for (i=0;i<BaseAlloc.TotAllocata;i++) {
			if (BaseAlloc.VetAllocata[i].pBaseMem) {
				BaseAlloc.VetAllocata[j] = BaseAlloc.VetAllocata[i];
				j++;
			}
		}
		BaseAlloc.TotAllocata=j;
	}

}
// incrementa il numero di debug attivi
// se alla fine c'e' un valore attivo di debug restitusice true
bool AddTabLogScript(void)
{
	if ((GlobTomb4.ScriptOptions.MainFlags & ngfm_Diagnostica)!=0 && 
		(GlobTomb4.pDiagnostica->FlagsDgx & DGX_LOG_SCRIPT_COMMANDS) !=0) {

		GlobTomb4.DebugModeCounter++;
	}

	if (GlobTomb4.DebugModeCounter) return true;
	return false;

}


// sospende temporaneamente logscript
// questo non riguarda la sospensione col tasto f9
// ma una sospensione per eliminare solo qualche procedura dal log
// WORD OldFlagsDgx;
// int OldDebugCounter;
// i valori attuali vengono salvati in  VetOldDebug[] record

void SospendiLogScript(int IndiceSave)
{

	VetSalvaOldDebug[IndiceSave].OldFlagsDgx = GlobTomb4.pDiagnostica->FlagsDgx;
	VetSalvaOldDebug[IndiceSave].OldCounter  = GlobTomb4.DebugModeCounter;

	GlobTomb4.DebugModeCounter=0;
	GlobTomb4.pDiagnostica->FlagsDgx &= ~DGX_LOG_SCRIPT_COMMANDS;

}
void GestioneLaraHp(void)
{
	BYTE Livello;
	StrLaraHp *pLaraHp;
	int i;
	StrItemTr4 **p2Lara = (StrItemTr4 **) 0x80E01C;
	StrItemTr4 *pLara;

	Livello = *GlobTomb4.pAdr->pLevelNext;

	if (Livello == 0) return;

	pLaraHp = &GlobTomb4.BaseOldHpLara;

	pLara = *p2Lara;

	for (i=0;i<pLaraHp->TotTargetLevels;i++) {
		if (pLaraHp->VetTargetLevels[i] == KLH_ALL_LEVELS ||
			pLaraHp->VetTargetLevels[i] == Livello) {
			
			pLara->Health = pLaraHp->LastHpValue;	
			pLara->FlagsMain |= 0x10;
			return;

		}
	}

	
}
// restituisc el astruttura MyRect di rettangolo di script CUST_RECT
// se non lo trova restiuisce NULL e il messaggio d'errore e' gia' stato inviato
StrMyRect* GetMyRect(int IdRect)
{
	int Indice;

	if (IdRect < 0 || IdRect >= (MAX_MY_RECT*10)) {
		sprintf(BufferLog,"ERROR: invalid ID for rect structure (%d)", IdRect);
		InviaLog(BufferLog);
		return NULL;
	}
	Indice = GlobTomb4.BaseParamMyRects.VetId[IdRect];

	if (Indice==-1) {
		sprintf(BufferLog, "ERROR: missing command Parameters=PARAM_RECT with id=%d", IdRect);
		InviaLog(BufferLog);
		return NULL;
	}

	return &GlobTomb4.BaseParamMyRects.VetMyRect[Indice];

}

// aggiunge idati di mesh attuale bel buffer delle mesh da visualizzare
// nota: se Slot = negativo allor ae' l'indice di un oggetto statico
// da cui prelvare il numero di mesh
void AddShowMesh(StrPosizione *pPos, short HOrient, short VOrient, short ROrient, 
				 short Slot, short NMesh)
{
	int i;
	StrShowMeshAbs *pShow;
	StrMeshInfo *pMeshInfo;
	int IndiceRoom;
	int IndiceStatic;
	StrStaticSlot *pEdit;

	i = GlobTomb4.BaseShowMesh.TotMesh;
	if (i >= MAX_SHOW_MESH) {
		InviaLog("WARNING: Reached max number of show mesh data");
		return;
	}

	pShow = &GlobTomb4.BaseShowMesh.VetMesh[i];
	pShow->PosData.Posizione = *pPos;

	if (Slot < 0) {
		// e' uno statico
		i = -Slot;
		IndiceRoom = GlobTomb4.VetRemapStatics[i].IndiceRoom;
		IndiceStatic = GlobTomb4.VetRemapStatics[i].IndiceStatic;
		pMeshInfo = &GlobTomb4.pAdr->pVetRooms[IndiceRoom].Ptr_StaticMesh[IndiceStatic];
		
		i = pMeshInfo->SlotId;
		pEdit = &GlobTomb4.pAdr->pVetEditObjects[i];
		pShow->Mesh = pEdit->IndiceMesh;
		

	}else {
		// e' la mesh di un moveable
		
		pShow->Mesh = GlobTomb4.pAdr->pVetSlot[Slot].IndexFirstMesh + NMesh;
	}

	pShow->PosData.OrientH = HOrient;
	pShow->PosData.OrientR = ROrient;
	pShow->PosData.OrientV = VOrient;

	GlobTomb4.BaseShowMesh.TotMesh++;

}

