// inserisce in campo 7F7731: Savegame_1E8_CheckSum  (BYTE)
// legge i dati divisi in due parti:
// una parte da 0x57 ossia da 7F75A0: BaseSavegame
// poi la parte piu' grossa quella dei moveable ora parte da 
// GlobTomb4.BaseRemap.Old_7F7769
void CalcolaCheckSum(void)
{

	BYTE *pParteFissa = (BYTE *) 0x7F75A0;
	BYTE *pValCheck = (BYTE *) 0x7F7731;
	int Somma1;
	int Somma2;
	int i;
	BYTE *pMov;
	int TotBytes;
	int TotMobile;
	int SommaFinale;
	
	TotBytes = 0x7FA9;  // 32681


	Somma1=0;
	*pValCheck = 0;
	for (i=0;i<457;i++) {
		Somma1 += pParteFissa[i];
	}

	// ora parte variabile
	// 32224 + 457 = 32681 (0x7FA9)
	TotMobile = TotBytes - 457;
	// eccola! la differenza nuova!!!
	pMov = (BYTE *) GlobTomb4.BaseRemap.Old_7F7769.Start;
	Somma2=0;
	for (i=0;i<TotMobile;i++) {
		Somma2 += pMov[i];
	}
	SommaFinale = Somma1+Somma2;
	SommaFinale &=255;
	SommaFinale = -SommaFinale;
	*pValCheck = SommaFinale & 255;





}
// chiama tutti le callback CB_INIT_GAME
void GestionCallBackINIT_GAME(void)
{

	DWORD i;
	struct StrPluginRec *pPlugin;
	CALL_VOID pCallBack;  // prototipo per chiamare la procedura 

	for (i=1;i<MyGlobPrivate.DataBase.TotPlugins;i++) {
		pPlugin= &MyGlobPrivate.DataBase.pVetPlugins[i];

		pCallBack = (CALL_VOID) pPlugin->VetDirectCB[CB_INIT_GAME];
		if (pCallBack != NULL) {
			sprintf(BufferLog, "Begin calling CB_INIT_GAME callback for '%s' plugin", pPlugin->Nome);
			InviaErroreLog(BufferLog, i, false);
			
			pCallBack();
			InviaErroreLog("\tCompleted callback: ok", i, false);

	
		}

	}


}
// chiamata in fase caricamento di tr4 quando ancora
// le mesh sono uguali a quelle in file tr4
// salva il numero di vertici per ogni singola mesh
// salva in GlobTomb4.pVetSalvaSizeMesh[]
void SalvaDimensioniMesh(WORD *VetPtrMesh[], int TotMesh)
{
	int i;
	WORD *pPunta;
	char *pMex;



	

#ifdef LOG_MESH
	sprintf(BufferLog,"SalvaDimensioniMesh()  TotMeshPointers = %d 0x%X",
		TotMesh,TotMesh);
	InviaLog(BufferLog);
#endif
	// allocare memoria necessaria
	//a ttenzione questo viene chiamato ad ogni livello
	// per cui dovrei prima liberar eprecedente memoria

	if (GlobTomb4.pVetSalvaSizeMesh != NULL) FreeMine(GlobTomb4.pVetSalvaSizeMesh);

	GlobTomb4.pVetSalvaSizeMesh = (WORD *) MallocMine(TotMesh * 2, "pVetSalvaSizeMesh in SalvaDimensioniMesh()");


	for (i=0;i<TotMesh;i++) {
		pPunta = VetPtrMesh[i];
		if (pPunta[5] > 255) 
			pMex= "\t**** MAGGIORE DI 255 *******";
		else
			pMex="";

		//tot vertici e' all'offset 10 0x0A quindi la 5a word
		GlobTomb4.pVetSalvaSizeMesh[i] = pPunta[5];
#ifdef LOG_MESH
		sprintf(BufferLog,"\tIndex=%03d: 0x%08X  VerticesAmount=%d %s",
			i, pPunta, GlobTomb4.pVetSalvaSizeMesh[i],pMex);
		InviaLog(BufferLog);
#endif
	}
		
}
// controlla se mesh con numero indice IndiceMesh (raddoppiato)
// e' una mesh normale e il numero pNVertci corrisponde a nvertici
// oppure e' una mesh stramba 
// se la mesh e' normale restituisce true
// altrimenti false
bool ControllaVerticiMesh(int IndiceMesh, WORD *pNVertici)
{
	WORD VerticesAmount;
	int  i;

	VerticesAmount=*pNVertici;
	i = IndiceMesh / 2;
#ifdef LOG_MESH
	InviaLog("ControllaVerticiMesh()");

	sprintf(BufferLog,"\tpVertici=0x%08X  TotVert=0x%X IndiceDoppio=0x%X  VetSalvaMesh[%d]=0x%X",
		pNVertici, VerticesAmount,IndiceMesh, i,GlobTomb4.pVetSalvaSizeMesh[i]);
	InviaLog(BufferLog);
#endif
	if (VerticesAmount & 0xff) {
#ifdef LOG_MESH
		InviaLog("UGUALE perche' byte basso diverso da zero");
#endif

		return true;
	}

	
	if (VerticesAmount == 0) {
#ifdef LOG_MESH
		InviaLog("DIVERSO perche' uguale a zero");
#endif
		return false;
	}


	if (VerticesAmount == GlobTomb4.pVetSalvaSizeMesh[i]) {
#ifdef LOG_MESH
		InviaLog("\tUGUALE");
#endif
		return true;
	}
	else {
#ifdef LOG_MESH
		InviaLog("\tDIVERSO");
#endif
		return false;
	}

	
}

