// usando vettore remap trova indicetom corrispondente
// indice tail tr4
// se non la trova restituisce -1

int TailTr4ToTom(int  IndiceTr4) 
{
	int i;
	
	for (i=0;i<GlobTomb4.BaseRemapTail.TotTails;i++) {
		if (GlobTomb4.BaseRemapTail.VetRemapTail[i].IndiceTr4 == 
			IndiceTr4) {	
			return GlobTomb4.BaseRemapTail.VetRemapTail[i].IndiceTom;
		}
	}
#ifdef LOG_ANIMATED
	sprintf(BufferLog,"ERROR: cann't find a conversion for tr4 tail index=%d",
		IndiceTr4);
	InviaLog(BufferLog);
#endif
	return -1;

}

int TailTomToTr4(int  IndiceTom) 
{
	int i;
	
	for (i=0;i<GlobTomb4.BaseRemapTail.TotTails;i++) {
		if (GlobTomb4.BaseRemapTail.VetRemapTail[i].IndiceTom  == 
				IndiceTom) return GlobTomb4.BaseRemapTail.VetRemapTail[i].IndiceTr4 ;
	}
#ifdef LOG_ANIMATED
	sprintf(BufferLog,"ERROR: cann't find a conversion for tom tail index=%d",
		IndiceTom);
	InviaLog(BufferLog);
#endif
	return -1;

}
void MostraLogTexTail(StrTexInfoTr4 *pTex) 
{
	POINT TopLeft;
	POINT TopRight;
	POINT BottomRight;
	POINT BottomLeft;
	int SizeTex_X;
	int SizeTex_Y;


	// ora bisogna scoprire l'altezza originale della texture
	TopLeft.x = FloatCord2Int(pTex->TopLeft[0]);
	TopLeft.y = FloatCord2Int(pTex->TopLeft[1]);

	TopRight.x = FloatCord2Int(pTex->TopRight[0]);
	TopRight.y = FloatCord2Int(pTex->TopRight[1]);

	BottomRight.x = FloatCord2Int(pTex->BottomRight[0]);
	BottomRight.y = FloatCord2Int(pTex->BottomRight[1]);

	BottomLeft.x = FloatCord2Int(pTex->BottomLeft[0]);
	BottomLeft.y = FloatCord2Int(pTex->BottomLeft[1]);


	SizeTex_X = TopRight.x - TopLeft.x +1;
	SizeTex_Y = BottomRight.y -  TopRight.y + 1;
	sprintf(BufferLog,"\t\t\tAttribute=0x%X", pTex->Attribute);
	InviaLog(BufferLog);

	sprintf(BufferLog,"\t\t\tTail=0x%X", pTex->Tail );
	InviaLog(BufferLog);

	sprintf(BufferLog,"\t\t\tFlags=0x%X", pTex->Flags);
	InviaLog(BufferLog);

	sprintf(BufferLog,"\t\t\tTopLeft(%d, %d)", 
			TopLeft.x, TopLeft.y);
	InviaLog(BufferLog);

	sprintf(BufferLog,"\t\t\tTopRight(%d, %d)", 
			TopRight.x, TopRight.y);
	InviaLog(BufferLog);

	sprintf(BufferLog,"\t\t\tBottomRight(%d, %d)", 
			BottomRight.x, BottomRight.y);
	InviaLog(BufferLog);

	sprintf(BufferLog,"\t\t\tBottomLeft(%d, %d)", 
			BottomLeft.x, BottomLeft.y );
	InviaLog(BufferLog);
}

int Float2Cord(float Valore)
{
	float Temp;
	float *p1_256 = (float *) 0x4A7254;

	Temp = Valore / *p1_256;
	return (int) Temp;

}
