// record frame di tipo P-Frame appena inserito per cui l'indice
// e' sempre totframes - 1
// se le texture sono frammenti parziali le riordina
// in modo che abbiano lo stesso ordine delle texture del record primario full
void RiordinaPFrame(StrAnimFrame *pFrame)
{
	int IndiceTr4, IndiceTom;
	int IndiceRange;
	StrAnimFrame *pMainFrame;
	WORD VetFullTail[MAX_TEX_PER_FRAME];
	StrAnimFrame TempFrame;
	int i;
	int j;

	IndiceTr4 = pFrame->VetTailIndex[0];

	IndiceTom = TailTr4ToTom(IndiceTr4);

	if (IndiceTom == -1) {
		sprintf(BufferLog,"ERROR: cann't locate the tom index for tr4 tail index=%d", IndiceTr4);
		InviaLog(BufferLog);
		return;
	}
	// verificare che sia un texture parziale di qualche tipo
	if ((IndiceTom & (REMAP_FRAMMENTO + REMAP_TRIANGOLO + 
					REMAP_TRASPARENTE + REMAP_SPECULARE)) == 0) return;

	// ok e' un record p-frame e basato su texture parziali.
	// ora cercare il record di riferimento principale di queste texture
	IndiceTom &= 0x3ff;

	IndiceTr4 = TailTomToTr4(IndiceTom);

	if (IndiceTr4 == -1) {
		sprintf(BufferLog,"ERROR: cann't find the tr4 tail corresponding to tom tail=%d",
			IndiceTom);
		InviaLog(BufferLog);
		return;
	}

	// adesso cercare in quale range di tipo p-frame c'e' questa texture
	IndiceRange=-1;

	for (i=0;i<GlobTomb4.BaseAnimTr4.TotFrameRanges-1;i++) {
		pMainFrame = &GlobTomb4.BaseAnimTr4.VetFrameRanges[i];
		for (j=0;j<pMainFrame->TotTextures;j++) {
			if (pMainFrame->VetTailIndex[j]  == IndiceTr4) {
				IndiceRange= i;
				break;
			}
		}
		if (IndiceRange != -1) break;
	}

	if (IndiceRange == -1) {
		sprintf(BufferLog,"ERROR: cann't locate the main p-frame with full tail=%d", IndiceTr4);
		InviaLog(BufferLog);
		return;
	}
	// trovato il frame principale.
	// ora per ogni tail parziale del frame principale
	// trovare la tail full corrispondente e quindi usare
	// quest'ultima per capire il nuovo ordine da assegnare.
	for (i=0;i<pFrame->TotTextures;i++) {
		IndiceTr4=pFrame->VetTailIndex[i];

		IndiceTom = TailTr4ToTom(IndiceTr4);

		if (IndiceTom==-1) return;

		IndiceTom &= 0x3ff;

		IndiceTr4 = TailTomToTr4(IndiceTom);

		if (IndiceTr4 ==-1) return;

		VetFullTail[i] = IndiceTr4;
	}

	// ora ora per ogni texture scoprire in che posizione andra' realmente
	// copiato.
	// per farlo usare un altro record temporaneo
	TempFrame.TotTextures= pFrame->TotTextures;

	for (i=0;i<pFrame->TotTextures;i++) {
		IndiceTr4 = VetFullTail[i];

		for (j=0;j<pMainFrame->TotTextures;j++) {
			if (pMainFrame->VetTailIndex[j] == IndiceTr4) break;
		}
		if (j == pMainFrame->TotTextures) return;

		// ok la tex che in frame frammenti e' in posizione [i] metterla
		// in posizione [j]

		TempFrame.VetTailIndex[j] = pFrame->VetTailIndex[i];
		TempFrame.VetTexInfoRecords[j] = pFrame->VetTexInfoRecords[i];
	}

	// ok, ora copiare dal record temp di nuovo al mio frame 

	for (i=0;i<pFrame->TotTextures;i++) {
		pFrame->VetTailIndex[i] = TempFrame.VetTailIndex[i];
		pFrame->VetTexInfoRecords[i] = TempFrame.VetTexInfoRecords[i];
	}

}

// inizializza dati globali per animare texture, sia frame che uv
void InitTextureAnimateTomb4(void)
{
	int *pContatoreCicliFrame = (int*) 0x5C0348;
	WORD **Ptr_VetAnimatedTextures = (WORD **) 0x753B44;
	WORD *VetAnimatedTextures;
	// attenzione questo e' stato rilocato, prima era 0x533270
	int  *pTotUVRange = (int*) 0x4A6D30;

	char *pScript_UV_Rotate = (char*) 0x7FD1C9;
	int IndiceTail;
	int k;
	int i;
	int Indice;

	WORD TempWord;
	int TotRiverRange;
	StrRiverRange VetRiverRange[40];
	WORD SalvaTipo;
	bool TestGiaFatto;
	bool TestSalta;
	float *pVetVertici;
	int n;
	float AltoY, BassoY;
	int TrianglesAmount;
	WORD VetTriangoli[4096];

	float OrgX, OrgY, FSizeX, FSizeY, OffX, OffY;
	StrBaseAnimTr4 *pAnimTr4;
	int IndiceFull,IndiceParziale;
	int IndiceTom;
	int z;
	int SizeTex_X;
	int TotRanges;
	int NumTex;
	int IndiceRange;
	int j;
	int SizeTex_Y;
	int SettingUvRotate;
	int SettingDelay;
	int TotFrameRanges;
	int IndiceFullNow;
	int TotSpeculari;
	int VetSpeculari[4096];
	StrTexInfoTr4 *pTex;
	StrTexInfoTr4 *pTexFull;
	StrTexParziali *pParziale;
	WORD WordSettings;
	StrAnimUVRotate *pMyRotate;
	StrAnimUVRotate *pMyNewRotate;
	StrAnimFrame *pMyFrame;
	POINT TopLeft;
	POINT TopRight;
	POINT BottomRight;
	POINT BottomLeft;
	WORD SettingTipoAnim;
	bool TestScrolling;
	StrDatiExtraAnimazioni *pExtra;
	int IndiceRangeNG;
	int OldIndiceRangeNG;
	int IndiceVerticeTop;
	int TotTrasparenti;
	int VetTrasparenti[4096];
	int TotParziali;
	WORD VetParziali[4096];
	StrTexInfoTr4 ** p2VetTexInfo = (StrTexInfoTr4 **) 0x533990;
	// NOTA: impostare indirizzo globale per texinfo perche
	// questa procedura viene chiamata prima di InizializzaStartLivello

	GlobTomb4.pAdr->VetTexInfo = *p2VetTexInfo;	
	
	// perfezione flag per conversione
	CorreggiRemapTail();

	pExtra = &GlobTomb4.TexAnimate;
	pAnimTr4 = &GlobTomb4.BaseAnimTr4;

	OldIndiceRangeNG = -2;


	VetAnimatedTextures = *Ptr_VetAnimatedTextures;

#ifdef LOG_ANIMATED
	ShowDatiRemapTail();
#endif

	i=0;
	TotRanges = VetAnimatedTextures[i++];

	GlobTomb4.BaseAnimTr4.TotUvRanges = 0;
	GlobTomb4.BaseAnimTr4.TotFrameRanges = 0;

	TotFrameRanges=0;

	IndiceFullNow=-1;


#ifdef LOG_ANIMATED
	ShowDatiTexParziali(&GlobTomb4.BaseTexParziali);
	sprintf(BufferLog,"TotRanges=%d  TotMultipleUV=%d",
		TotRanges, *pTotUVRange);
	InviaLog(BufferLog);
#endif
	IndiceRangeNG=0;
	TotRiverRange=0;

	for (IndiceRange=0;IndiceRange<TotRanges;IndiceRange++) {




		// calcolare se bisogna incrementare indicenow per 
		// riferito a record animation di dati ng

		//  se questo range risulta essere di tipo scroll
		//  e contiene un triangolo ignoranrlo del tutto.
		// guardare
		// ora VetAnimatedTexutres[i] piunta a numero di texture
		// che seguono del range attuale

		// eliminare tutti gl ieventuali frame range creati
		// da tomc2pc su texture scrolling
		do {
			TestSalta=false;
			for (z=0;z<=VetAnimatedTextures[i];z++) {
				IndiceTail = VetAnimatedTextures[z+i+1];

				// prima controllare se questa tex e' un triangolo
				IndiceTom=TailTr4ToTom(IndiceTail);
				if (IndiceTom != -1) {
					if ((IndiceTom & REMAP_TRIANGOLO) ||
						(IndiceTom & REMAP_TRASPARENTE) ||
						(IndiceTom & REMAP_SPECULARE)) {

						// e' una texture triangolare  trasparente
						// o speculare
						// ora vedere se  fa parte
						// di una tail che e' inclusa in un range scroll
						SalvaTipo = IndiceTom;
						IndiceTom &= 0x3ff;
						
						// ok, ora vedre se IndiceFull e' una d quelle
						// di qualche range scroll
						for (j=0;j<pExtra->Tot_UV_Rotate;j++) {
							if (IndiceTom >= pExtra->VetFromTex[j] &&
								IndiceTom <= pExtra->VetToTex[j]) {
								// se il tipo indice tom e' transparent
								// e il range attuale e' di tipo river
								// allora salvarlo in modo da aggiungerlo
								// dopo alla fine
								if ((pExtra->VetInfoRangeAnim[j] & 
										FAN_MASK_ANIM) == 
											FAN_RIVER_ROTATE &&
											(SalvaTipo & REMAP_TRASPARENTE) != 0) {
									// salvare i dati di questo range
									VetRiverRange[TotRiverRange].TotTexture = 
										VetAnimatedTextures[i]+1;
									VetRiverRange[TotRiverRange].IndiceRangeNG  =
										IndiceRangeNG;

									// inserire il valore di frame
									TempWord = pExtra->VetInfoRangeAnim[j];
									TempWord &= FAN_MASK_FPS_UV;
									TempWord = TempWord >> 8;
									if (TempWord) {
										// se diverso da zero
										// convertirlo in tickcount
										TempWord = 1000 / TempWord;

									}
									VetRiverRange[TotRiverRange].SettingFps=
										TempWord;

									for (k=0;k<=VetAnimatedTextures[i];k++) {
										VetRiverRange[TotRiverRange].
												VetIndiciTail[k] =
												  VetAnimatedTextures[i+k+1];
									}
									TotRiverRange++;
								}
									
								TestSalta=true;
								break;
							}
						}
						if (TestSalta==true) break;
					}
				}
			}

			if (TestSalta==true) {
				// saltare del tutto il range attuale da tr4
				i = i + VetAnimatedTextures[i] +2;
#ifdef LOG_ANIMATED
				sprintf(BufferLog,"WARNING: SKIPPED FRAME RANGE %d",
					IndiceRange);
				InviaLog(BufferLog);
#endif

				IndiceRange++;
			}
		}while (TestSalta==true);
		// come prima cosa calcolare se questo range
		// e' relativo a uvscroll oppure a frame
		// impostare indice preciso e TestScrolling
		IndiceRangeNG=-1;
		for (z=0;z<=VetAnimatedTextures[i];z++) {
			IndiceTail = VetAnimatedTextures[z+i+1];
			IndiceTom=TailTr4ToTom(IndiceTail);

			SalvaTipo = IndiceTom;
			IndiceTom &= 0x3ff;
			
			// ok, ora vedre se IndiceFull e' una d quelle
			// di qualche range scroll
			for (j=0;j<pExtra->TotaleRangeNG;j++) {
				if (IndiceTom >= pExtra->VetFromTex[j] &&
					IndiceTom <= pExtra->VetToTex[j]) {
					// trovato range di appartenenza
					if (j >= pExtra->Tot_UV_Rotate) 
						TestScrolling=false;
					else
						TestScrolling=true;

					IndiceRangeNG = j;
					break;
				}
			}
			if (IndiceRangeNG != -1) break;
		}

		if (IndiceRangeNG==-1) {
			if (MyGlobPrivate.TestNG_NoTr4 == false) {
				sprintf(BufferLog,"ERROR: cann't locate ng frame range for texture of %dth anim range of tr4 file",
					IndiceRange);
				InviaLog(BufferLog);
			}
			// imposta valori generici per agire come animaione frame
			TestScrolling=false;
			IndiceRangeNG = -1;

	

		}
#ifdef LOG_ANIMATED
		sprintf(BufferLog,"================= RANGE Tr4=%d NG=%d UV=%d ===============", 
				IndiceRange, IndiceRangeNG, TestScrolling);
		InviaLog(BufferLog);
#endif		
		NumTex = VetAnimatedTextures[i++];

		if (TestScrolling==true) {
			if (IndiceRangeNG != -1) {
				WordSettings = pExtra->VetInfoRangeAnim[IndiceRangeNG];
			}else {
				WordSettings = 0;
			}
			// e' un range di tipo UV: impostare tutto
			pMyRotate = &GlobTomb4.BaseAnimTr4.
						VetUVRanges[GlobTomb4.BaseAnimTr4.TotUvRanges];

			TotParziali=0;
			TrianglesAmount=0;
			TotTrasparenti=0;
			TotSpeculari=0;
			pMyRotate->IndiceRangeNG=IndiceRangeNG;

			for (j=0;j<=NumTex;j++) {
				IndiceTail = VetAnimatedTextures[i++];
				pTex = &GlobTomb4.pAdr->VetTexInfo[IndiceTail];


				// copiare TopY  per conoscere origine y (lasciare float)
				pMyRotate->VetOrgY[j] = pTex->TopLeft[1];
				pMyRotate->VetTailIndex[j] = IndiceTail;

				// ora bisogna scoprire l'altezza originale della texture
				TopLeft.x = FloatCord2Int(pTex->TopLeft[0]);
				TopLeft.y = FloatCord2Int(pTex->TopLeft[1]);

				TopRight.x = FloatCord2Int(pTex->TopRight[0]);
				TopRight.y = FloatCord2Int(pTex->TopRight[1]);
	
				BottomRight.x = FloatCord2Int(pTex->BottomRight[0]);
				BottomRight.y = FloatCord2Int(pTex->BottomRight[1]);

				BottomLeft.x = FloatCord2Int(pTex->BottomLeft[0]);
				BottomLeft.y = FloatCord2Int(pTex->BottomLeft[1]);


				SizeTex_X = TopRight.x - TopLeft.x +1;
				SizeTex_Y = BottomRight.y -  TopRight.y + 1;

#ifdef LOG_ANIMATED
				// mostrare tutti i dati di questa texture
				sprintf(BufferLog, "IndiceRange=%d (RangeNG=%d)  IndiceTail=%d  Size(%d,%d)",
					IndiceRange, IndiceRangeNG, IndiceTail, SizeTex_X, SizeTex_Y);
				InviaLog(BufferLog);
				sprintf(BufferLog,"\t\tAttribute=0x%X", GlobTomb4.pAdr->VetTexInfo[IndiceTail].Attribute);
				InviaLog(BufferLog);

				sprintf(BufferLog,"\t\tTail=0x%X", GlobTomb4.pAdr->VetTexInfo[IndiceTail].Tail );
				InviaLog(BufferLog);

				sprintf(BufferLog,"\t\tFlags=0x%X", GlobTomb4.pAdr->VetTexInfo[IndiceTail].Flags);
				InviaLog(BufferLog);

				sprintf(BufferLog,"\t\tTopLeft(%d, %d)", 
						TopLeft.x, TopLeft.y);
				InviaLog(BufferLog);

				sprintf(BufferLog,"\t\tTopRight(%d, %d)", 
						TopRight.x, TopRight.y);
				InviaLog(BufferLog);

				sprintf(BufferLog,"\t\tBottomRight(%d, %d)", 
						BottomRight.x, BottomRight.y);
				InviaLog(BufferLog);

				sprintf(BufferLog,"\t\tBottomLeft(%d, %d)", 
						BottomLeft.x, BottomLeft.y );
				InviaLog(BufferLog);
#endif
				// adesso cercare texture associate:
				// come frammenti,come triangoli o come trasparenti

				// ora cercare in texparziali per
				// vedere se ci sono frammenti per questa texture
				IndiceTom = TailTr4ToTom(IndiceTail);
				if (IndiceTom != -1) {
					//ok, ora cercare se ci sono tex parziali
					// per questa indice tail
					for (z=0;z<GlobTomb4.BaseTexParziali.TotRecords;z++) {
						if (GlobTomb4.BaseTexParziali.
								VetParziali[z].IndiceFull == IndiceTom) {
							// trovato, salvarlo
							VetParziali[TotParziali++] = z;
						}
					}
					
				}
				// ora cercare se ci sono triangoli o trasparenti o speculari
				 // che corrispondo a indicetail attuale
				for (z=0;z<GlobTomb4.BaseRemapTail.TotTails;z++) {
					TestGiaFatto=false;
					if (GlobTomb4.BaseRemapTail.
							VetRemapTail[z].IndiceTom & REMAP_TRIANGOLO) {
						// trovato un triangolo
						// ora se l'indice tr4 corrispondnte
						// e' la IndiceTail attuale, allora
						// salvare questo indice
						IndiceTom = GlobTomb4.BaseRemapTail.
									VetRemapTail[z].IndiceTom;
						if (TailTomToTr4(IndiceTom & (MAX_TAIL_INFOS -1)) == IndiceTail) {

							VetTriangoli[TrianglesAmount++]=z;
							TestGiaFatto=true;
						
						}
					}
					if (TestGiaFatto == false) {
						// vedere se e'una tex trasparente
						if (GlobTomb4.BaseRemapTail.
								VetRemapTail[z].IndiceTom & REMAP_TRASPARENTE) {
							// vedere se corrisponde a indicetail attuale
							IndiceTom = GlobTomb4.BaseRemapTail.
									VetRemapTail[z].IndiceTom;
						
							if (TailTomToTr4(IndiceTom & 0x3ff) == IndiceTail) {							
								TestGiaFatto=true;
								VetTrasparenti[TotTrasparenti++] = 
									GlobTomb4.BaseRemapTail.
										VetRemapTail[z].IndiceTr4;
							}
						}
						
					}
					if (TestGiaFatto==false) {
						// vedere se e' una tex speculare
						if (GlobTomb4.BaseRemapTail.VetRemapTail[z].IndiceTom & REMAP_SPECULARE) {
							// vedere se corrisponde a indicetail attuale
							IndiceTom = GlobTomb4.BaseRemapTail.
									VetRemapTail[z].IndiceTom;
						
							if (TailTomToTr4(IndiceTom & 0x3ff) == IndiceTail) {							
								TestGiaFatto=true;
								VetSpeculari[TotSpeculari++] = 
									GlobTomb4.BaseRemapTail.
										VetRemapTail[z].IndiceTr4;
							}
						}
					}

				}


			}

			// ora impostare valori diversi a seconda
			// se il tipo di animazione e' half-scroll o full-scroll
			if (GlobTomb4.TexAnimate.TestPresente ==false ){
				// se non c'e' l'header considerare tutte le impostazioni
				// come quelle standard
				SettingUvRotate = *pScript_UV_Rotate;
				SettingDelay = 0;
				SettingTipoAnim = FAN_HALF_ROTATE;
			}else {

				
				TempWord = WordSettings & FAN_MASK_FPS_UV;
				TempWord = TempWord >> 8;
				if (TempWord) {
					TempWord = 1000 / TempWord;
				}
				// se pero' questo range e' di tipo river
				// allora mettere sempre valore massimo ossia ritardo 0

				if ((SettingTipoAnim & FAN_MASK_ANIM) ==FAN_RIVER_ROTATE)
							TempWord=0;
				SettingDelay = TempWord;

				SettingTipoAnim = WordSettings & FAN_MASK_ANIM;
				// calcolo uvrotate
				TempWord = WordSettings & FAN_MASK_UVROTATE;
				SettingUvRotate = (char) TempWord;
				if (SettingUvRotate == 0) {
					// richiesta di uvrotate di script ,ossia default
					SettingUvRotate = *pScript_UV_Rotate;
					SettingTipoAnim |= 1;  // segnala uso default
				}
				
			}
			// ora inizializzare valori globali per tutto questo range
			pMyRotate->TestStop=false;
			pMyRotate->LastTime = 0;
			pMyRotate->DelayTime = SettingDelay;
			pMyRotate->ScrollPos= 0;
			pMyRotate->TestTriangolo=false;
			// vedere se vanno aggiunte altre texture
			// attenzione: (molto complicato)
			// se questa tex trasparenti e' relativa
			// ad animazione river, inserire in nuovi range
			// scroll queste texture
			n = NumTex+1;
			if (TotTrasparenti) {

				if (IndiceRangeNG == -1 || 
					(pExtra->VetInfoRangeAnim[IndiceRangeNG] & FAN_RIVER_ROTATE) !=
						FAN_RIVER_ROTATE) {

					// e' normale range trasparente: aggiungere
					// solo le texture al range gia' presente

					for (z=0;z<TotTrasparenti;z++) {
						IndiceTail = VetTrasparenti[z];
						pMyRotate->VetOrgY[n] = 
								GlobTomb4.pAdr->VetTexInfo[IndiceTail].TopLeft[1];
						pMyRotate->VetTailIndex[n] = IndiceTail;
						n++;
					}
				}
			}
			// vedere se ci sono speculari
			for (z=0;z<TotSpeculari;z++) {
				IndiceTail = VetSpeculari[z];
				pMyRotate->VetOrgY[n] = GlobTomb4.pAdr->VetTexInfo[IndiceTail].TopLeft[1];
				pMyRotate->VetTailIndex[n] = IndiceTail;
				n++;
			}				
			pMyRotate->TotTextures= n;
			pMyRotate->UvRotate = SettingUvRotate;
			pMyRotate->TipoAnim = SettingTipoAnim;

			// mezza rotazione. considerare spostamento di mezza tex
			SizeTex_Y /= 2;
	

			pMyRotate->Height = IntCord2Float(SizeTex_Y);
			pMyRotate->Maschera = SizeTex_Y-1;
			// aumnentare numero di record range
			GlobTomb4.BaseAnimTr4.TotUvRanges++;

			// ora aggiungere tutti gli eventuali range
			// necessari per tex parziali

			for (z=0;z<TotParziali;z++) {
				j = VetParziali[z];
				pParziale = &GlobTomb4.BaseTexParziali.VetParziali[j];

				IndiceFull = TailTomToTr4(pParziale->IndiceFull);
				IndiceParziale = TailTomToTr4(pParziale->IndiceFrammento);
#ifdef LOG_ANIMATED
				sprintf(BufferLog,"\t\tFRAMMENTO: IndiceParziale=%d di IndiceFull=%d",
					IndiceParziale, IndiceFull);
				InviaLog(BufferLog);
#endif
				OffX = IntCord2Float(pParziale->OffX);
				OffY = IntCord2Float(pParziale->OffY);

				pMyNewRotate = &GlobTomb4.BaseAnimTr4.
						VetUVRanges[GlobTomb4.BaseAnimTr4.TotUvRanges];

				pMyNewRotate->IndiceRangeNG=IndiceRangeNG;

				// per adesso copiare quasi tutti i dati
				pTex = &GlobTomb4.pAdr->VetTexInfo[IndiceParziale];
				pTexFull = &GlobTomb4.pAdr->VetTexInfo[IndiceFull];
#ifdef LOG_ANIMATED
				sprintf(BufferLog,"DATI DI TEXTURE FULL %d",
					IndiceFull);
				InviaLog(BufferLog);
				MostraLogTexTail(pTexFull);

#endif
				// copiare TopY  per conoscere origine y (lasciare float)
				pMyNewRotate->TotTextures = 1;
				pMyNewRotate->VetOrgY[0] = pTexFull->TopLeft[1];
				pMyNewRotate->VetTailIndex[0] = IndiceParziale;

				// ora bisogna scoprire l'altezza originale della texture
				TopLeft.x = FloatCord2Int(pTex->TopLeft[0]);
				TopLeft.y = FloatCord2Int(pTex->TopLeft[1]);

				TopRight.x = FloatCord2Int(pTex->TopRight[0]);
				TopRight.y = FloatCord2Int(pTex->TopRight[1]);
	
				BottomRight.x = FloatCord2Int(pTex->BottomRight[0]);
				BottomRight.y = FloatCord2Int(pTex->BottomRight[1]);

				BottomLeft.x = FloatCord2Int(pTex->BottomLeft[0]);
				BottomLeft.y = FloatCord2Int(pTex->BottomLeft[1]);


				SizeTex_X = TopRight.x - TopLeft.x +1;
				SizeTex_Y = BottomRight.y -  TopRight.y + 1;

				FSizeX = IntCord2Float(SizeTex_X-1);
				FSizeY = IntCord2Float(SizeTex_Y-1);
#ifdef LOG_ANIMATED
				sprintf(BufferLog, "\t\tPRIMA MODIFICHE: IndiceRange=%d  IndiceTail=%d  Size(%d,%d)",
					IndiceRange, IndiceTail, SizeTex_X, SizeTex_Y);
				InviaLog(BufferLog);

				MostraLogTexTail(pTex);
#endif
				// bisogna alterare direttamente i valori
				// della tail info parziale in modo da farla puntare
				// sopra a texture full
				
				pTex->Tail= pTexFull->Tail;
				pTex->TopLeft[0] = pTexFull->TopLeft[0] + OffX;
				pTex->TopLeft[1] = pTexFull->TopLeft[1] + OffY;

				OrgX = pTex->TopLeft[0];
				OrgY = pTex->TopLeft[1];
	
				pTex->TopRight[0] = OrgX + FSizeX;
				pTex->TopRight[1] = OrgY;


				pTex->BottomRight[0] = OrgX+FSizeX;
				pTex->BottomRight[1] = OrgY+FSizeY;

				pTex->BottomLeft[0] = OrgX;
				pTex->BottomLeft[1] = OrgY+FSizeY;
#ifdef LOG_ANIMATED
				// mostrare tutti i dati di questa texture
				sprintf(BufferLog, "\t\tDOPO MODIFICHE: IndiceRange=%d  IndiceTail=%d  Size(%d,%d)",
					IndiceRange, IndiceTail, SizeTex_X, SizeTex_Y);
				InviaLog(BufferLog);

				MostraLogTexTail(pTex);
#endif
				// ora inizializzare valori globali per tutto questo range
				pMyNewRotate->TestStop=false;
				pMyNewRotate->LastTime = 0;
				pMyNewRotate->DelayTime = SettingDelay;

				if ((SettingTipoAnim & FAN_MASK_ANIM) ==FAN_HALF_ROTATE) OffY=0;

				pMyNewRotate->ScrollPos= FloatCord2Int( OffY);

				pMyNewRotate->UvRotate = SettingUvRotate;
				pMyNewRotate->TipoAnim = SettingTipoAnim;

				// per frammenti scroll considerare l'altezza
				// effettiva del frammento
				// mentre per la maschera di scorrimento
				// usare la dimensione della dimensione di default
				// diminuire la dimensione y solo e anche il tipo
				// di scorrimento e' halfrotate
				if ((SettingTipoAnim & FAN_MASK_ANIM) ==FAN_HALF_ROTATE)
								SizeTex_Y /= 2;

				pMyNewRotate->Height = IntCord2Float(SizeTex_Y);

				if ((SettingTipoAnim & FAN_MASK_ANIM) ==FAN_HALF_ROTATE) {
					j = SizeTex_Y;
					j /= 2;
				}else {
					// scorrimento full
					j = pExtra->SizeDefault;
				}

				pMyNewRotate->Maschera = j -1;
				// aumnentare numero di record range
				GlobTomb4.BaseAnimTr4.TotUvRanges++;
			}

			// analisi per ricercare triangoli sovrapposti 
			// alle texture full di questo range
			for (z=0;z<TrianglesAmount;z++) {
				Indice = VetTriangoli[z];
				IndiceTom = GlobTomb4.BaseRemapTail.
									VetRemapTail[Indice].IndiceTom;
				IndiceTom &= 0x3ff;
				IndiceFull = TailTomToTr4(IndiceTom);
				IndiceParziale = GlobTomb4.BaseRemapTail.
									VetRemapTail[Indice].IndiceTr4;
				if (IndiceFull == -1) {
					// errore
#ifdef LOG_ANIMATED
					sprintf(BufferLog,"ERROR: cann't locate the tail info for animated triangle of %d tail",
						IndiceTom);
					InviaLog(BufferLog);
#endif
					break;
				}
				pMyNewRotate = &GlobTomb4.BaseAnimTr4.
						VetUVRanges[GlobTomb4.BaseAnimTr4.TotUvRanges];

				pTex = &GlobTomb4.pAdr->VetTexInfo[IndiceParziale];
				pMyNewRotate->IndiceRangeNG=IndiceRangeNG;

				pTexFull = &GlobTomb4.pAdr->VetTexInfo[IndiceFull];
#ifdef LOG_ANIMATED
				sprintf(BufferLog,"TRIANGOLO. DATI DI TEXTURE FULL %d",
					IndiceFull);
				InviaLog(BufferLog);
				MostraLogTexTail(pTexFull);

				sprintf(BufferLog,"TRIANGOLO. DATI DI TEXTURE FRAMMENTO %d",
					IndiceParziale);
				InviaLog(BufferLog);
				MostraLogTexTail(pTex);
#endif
				// ora bisogna trovare il valore cordy massimo
				// e minimo tra i primi tre campi
				// si, ma forse mi serve solo per la l'altezza
				AltoY=2;
				BassoY = -1;
				pVetVertici =  &pTex->TopLeft[0];
				for (j=1;j<6;j+=2) {
					// se questo range e' di tipo full scroll
					// diminuire dellameta' tutte le cordy
					pVetVertici[j] /=2;

					if (pVetVertici[j] < AltoY) {
						IndiceVerticeTop = j;
						AltoY = pVetVertici[j];
					}
					if (pVetVertici[j] > BassoY) {
						BassoY = pVetVertici[j];
					}
				}


				pMyNewRotate->TestTriangolo=true;
				pMyNewRotate->IndiceVerticeTop = IndiceVerticeTop;
				pMyNewRotate->Maschera = pExtra->SizeDefault-1;
				pMyNewRotate->TotTextures =1;
				pMyNewRotate->VetOrgY[0] = pTexFull->TopLeft[1];
				AltoY -= pMyNewRotate->VetOrgY[0];
				pMyNewRotate->ScrollPos = FloatCord2Int(AltoY);
				pMyNewRotate->VetTailIndex[0] = IndiceParziale;
				
				pMyNewRotate->TestStop=false;
				pMyNewRotate->LastTime = 0;
				pMyNewRotate->DelayTime = SettingDelay;

				pMyNewRotate->UvRotate = SettingUvRotate;
				pMyNewRotate->TipoAnim = SettingTipoAnim;

				// aumnentare numero di record range
				GlobTomb4.BaseAnimTr4.TotUvRanges++;


			}




		}else {
			// e' un range Frame con dati in IndiceRangeNg

			if (NumTex > MAX_TEX_PER_FRAME ) {
				sprintf(BufferLog, "ERROR: animated frame tex range %d, has too many tails %d (max allowed, for frame animation, is %d texs for frame)",
						pAnimTr4->TotFrameRanges, NumTex, MAX_TEX_PER_FRAME);
				InviaLog(BufferLog);


			}

			pMyFrame = &pAnimTr4->VetFrameRanges[pAnimTr4->TotFrameRanges];
			pMyFrame->IndiceRangeNG=IndiceRangeNG;
			pMyFrame->IndiceScrollRiver=-1;
			TotParziali=0;


			for (j=0;j<=NumTex;j++) {
				IndiceTail = VetAnimatedTextures[i++];
				// scoprire a che indice range originale
				// corrisponde il range attuale

				// copiare TopY  per conoscere origine y (lasciare float)
				if (j < MAX_TEX_PER_FRAME) {
					pMyFrame->VetTailIndex[j] = IndiceTail;
					pMyFrame->VetChangedPos[j] = j;
					pMyFrame->VetTexInfoRecords[j] = 
							GlobTomb4.pAdr->VetTexInfo[IndiceTail];
				}

			}
			//	queste codice qua sotto e' incomprensibile, che cazzo serve??
			// ho provato a correggere ma prima arrivava a scrivere 17 una in + del consentito
			if (NumTex < MAX_TEX_PER_FRAME) {
				pMyFrame->TotTextures= NumTex+1;
			}
			else {
				pMyFrame->TotTextures = MAX_TEX_PER_FRAME;
			}

			if (IndiceRangeNG != -1 ) {
				WordSettings = pExtra->VetInfoRangeAnim[IndiceRangeNG];
			}else {
				WordSettings =0;
			}
			if (GlobTomb4.TexAnimate.TestPresente == true) {

				SettingDelay = WordSettings;
			}else
			{	
				SettingDelay = 0;
			}

			pMyFrame->TipoAnim = SettingDelay & FAN_MASK_ANIM;
			pMyFrame->FrameToSet=0;
			pMyFrame->LastTime=0;
			pMyFrame->IndiceToSet = 0;

			if (pMyFrame->TipoAnim == FAN_P_FRAMES) 
				pMyFrame->TestStop =true;
			else
				pMyFrame->TestStop =false;

			pMyFrame->DelayTime = SettingDelay & 0x3fff;
			GlobTomb4.BaseAnimTr4.TotFrameRanges++;
			/*
			if (pMyFrame->TipoAnim == FAN_P_FRAMES) {
				RiordinaPFrame(pMyFrame);
			}
			*/
			


		}

	}

	// aggiungere eventuali range frame per animazione di tipo river
	for (i=0;i<TotRiverRange;i++) {
		// creare un nuvoo range ng
		
#ifdef LOG_ANIMATED
		sprintf(BufferLog,"ADDED  River Range %d", pExtra->TotaleRangeNG);
		InviaLog(BufferLog);
#endif
		pExtra->VetInfoRangeAnim[pExtra->TotaleRangeNG] = 
						VetRiverRange[i].SettingFps;

		pExtra->TotaleRangeNG++;
		IndiceRangeNG = VetRiverRange[i].IndiceRangeNG;

		pMyFrame = &pAnimTr4->VetFrameRanges[pAnimTr4->TotFrameRanges];
		pMyFrame->IndiceRangeNG = IndiceRangeNG;


		pAnimTr4->TotFrameRanges++;
	
		// ora inserire i dati
		for (j=0;j<VetRiverRange[i].TotTexture;j++) {
			IndiceTail = VetRiverRange[i].VetIndiciTail[j];
			pMyFrame->VetTailIndex[j] = IndiceTail;

			pMyFrame->VetTexInfoRecords[j] = 
					GlobTomb4.pAdr->VetTexInfo[IndiceTail];
		}
		pMyFrame->DelayTime = VetRiverRange[i].SettingFps;
		pMyFrame->TestStop =false;
		pMyFrame->TipoAnim = FAN_FRAMES;
		pMyFrame->TotTextures = VetRiverRange[i].TotTexture;
		pMyFrame->IndiceScrollRiver = GlobTomb4.BaseAnimTr4.TotUvRanges;

		// ---- ora creare range scrolling con stesse texture ----
		
		pMyRotate = &GlobTomb4.BaseAnimTr4.
				VetUVRanges[GlobTomb4.BaseAnimTr4.TotUvRanges];
		GlobTomb4.BaseAnimTr4.TotUvRanges++;
		pMyRotate->IndiceRangeNG = IndiceRangeNG;
		
		pMyRotate->TotTextures=VetRiverRange[i].TotTexture;
		for (j=0;j<VetRiverRange[i].TotTexture;j++) {

			IndiceTail = VetRiverRange[i].VetIndiciTail[j];
			pMyRotate->VetTailIndex[j] = IndiceTail;
			pMyRotate->VetOrgY[j] = 
				GlobTomb4.pAdr->VetTexInfo[IndiceTail].TopLeft[1];
		}
		IndiceTail = pMyRotate->VetTailIndex[0];

		pTex = &GlobTomb4.pAdr->VetTexInfo[IndiceTail];
		TopRight.y = FloatCord2Int(pTex->TopRight[1]);
		BottomRight.y = FloatCord2Int(pTex->BottomRight[1]);
		SizeTex_Y = BottomRight.y -  TopRight.y + 1;
		if (IndiceRangeNG !=-1) {
			WordSettings = pExtra->VetInfoRangeAnim[IndiceRangeNG];
		}else {
			WordSettings = 0;
		}
		// calcolo uvrotate
		TempWord = WordSettings & FAN_MASK_UVROTATE;
		SettingUvRotate = (char) TempWord;
		if (SettingUvRotate == 0) {
			// richiesta di uvrotate di script ,ossia default
			SettingUvRotate = *pScript_UV_Rotate;
			SettingTipoAnim |= 1;  // segnala uso default
		}
		SizeTex_Y /= 2;

		pMyRotate->Height = IntCord2Float(SizeTex_Y);
		pMyRotate->Maschera = SizeTex_Y-1;
		pMyRotate->UvRotate = SettingUvRotate;
		pMyRotate->TipoAnim = SettingTipoAnim;

		pMyRotate->TestStop=false;
		pMyRotate->LastTime = 0;
		pMyRotate->DelayTime = 0;

		pMyRotate->ScrollPos= 0;
		pMyRotate->TestTriangolo=false;

	
		

	}

	
#ifdef LOG_ANIMATED
	// per debug mostrare mostrare tutti i dati dei range creati
	ShowNuoviRange();
#endif
	
	
}


