// rimuove certe zone di codice di gestione skeleton se TestMettiNop == true
// per impedire modifiche a vitalita' skeleton
// se invece TestMettiNOP == false, ripristina codice originale
void CreaPatchSkeleton(bool TestMettiNOP)
{
	static DWORD * pZona1A = (DWORD*) 0x411A1C;
	static WORD * pZona1B = (WORD*) 0x411A20;

	static DWORD *pZona2 = (DWORD*) 0x412781;
	static DWORD *pZona3 = (DWORD*) 0x412794;

	if (TestMettiNOP) {
		// mette NOP per cancellare tre righe di codice
		*pZona1A = 0x90909090;
		*pZona1B = 0x9090;

		*pZona2 = 0x90909090;
		*pZona3 = 0x90909090;
	}else {
		// riprisitna codice originale
		*pZona1A = 0x2246c766;
		*pZona1B = 0x0019;

		*pZona2 = 0x224e8966;
		*pZona2= 0x224e8966;
	}
}

