	 pVetCostantiNemici[2].SuonoSparo = pWeap->SoundShot;
	 pVetCostantiNemici[2].DatoArmaEstratta = pWeap->Unknow;
	 pVetCostantiNemici[2].CordYArma = pWeap->VPositionOfWeapon;

	 // fucile
