	 pVetCostantiNemici[4].Random = pWeap->Dispersion;
	 pVetCostantiNemici[4].DistanceTarget = pWeap->DistanceAiming;

     pVetCostantiNemici[4].FrameCambioArma  = pWeap->FrameToTakeWeapon;
