	 pVetCostantiNemici[5].Random = pWeap->Dispersion;
	 pVetCostantiNemici[5].DistanceTarget = pWeap->DistanceAiming;

     pVetCostantiNemici[5].FrameCambioArma  = pWeap->FrameToTakeWeapon;
