	// intensita blinking light
	pByte = (BYTE *) 0x456A3b;
	*pByte = pCust->BlinkingLight.Blue;

	pByte = (BYTE *) 0x456A3D;
	*pByte = pCust->BlinkingLight.Verde;

	pByte = (BYTE *) 0x456A42;
