void EsegueAzioneWindowsFont(StrProgressiveAction *pAzione)
{
	char *pChar;
	static BYTE *pTestMonoScreen = (BYTE *) 0x536DEC;
	int i;
	bool TestMod;
	short Valore;
	DWORD Flags;
	DWORD SkipFlags;
	StrWindowsFont *pFont;
	RECT MioRect;
	
	StrParamWText *pWText;

	switch (pAzione->ActionType) {
		case AZ_PRINT_WINDOWS_STRING:
			if (pAzione->Arg1 != SCRIPT_IGNORE) pAzione->Arg1--;


			if (pAzione->ItemIndex == -1) {
				// e' testo per stringhe di sistema
				pChar = (char *) pAzione->VetArgDword[1];

				IsWindowsText(pAzione->VetArgShort[0], pAzione->VetArgShort[1], 
							pAzione->VetArgWord[6], pChar, pAzione->Arg2, pAzione->VetArgDword[2],true);
				if (pAzione->Arg1 ==0) {
					pAzione->ActionType=0;
							
					// liberare memoria

					FreeMine(pChar);
					pAzione->VetArgDword[1] = 0;


					
				}

				break;

			}
			break;
		case AZ_PRINT_WINDOWS_TEXT:
			i = GlobTomb4.BaseParamWText.VetIds[pAzione->ItemIndex];
			Flags = GlobTomb4.BaseParamWText.VetParamWText[i].Flags;

			SkipFlags = FindSkipPhase();

			if (SkipFlags & SKIP_GRAY_SCREEN) {
				// verificare se c'e' il flag che abuilita visualizzazione sopra monoscreen
				if ((Flags & WTF_OVER_INVENTORY) == 0) break;

			}
			if (SkipFlags & SKIP_FIXED_CAMERA) {
				// verificare se c'e' il flag che abuilita visualizzazione sopra fixcamera
				if ((Flags & WTF_OVER_FIXCAMERA) == 0) break;

			}

			if (SkipFlags & SKIP_FLY_CAMERA) {
				// verificare se c'e' il flag che abuilita visualizzazione sopra flycamera
				if ((Flags & WTF_OVER_FLYCAMERA) == 0) break;

			}
			if (SkipFlags & SKIP_FULL_IMAGE) {
				// verificare se c'e' il flag che abuilita visualizzazione sopra full image
				if ((Flags & WTF_OVER_IMAGE) == 0) break;

			}

			if (SkipFlags & SKIP_BINOCULARS) {
				// verificare se c'e' il flag che abuilita visualizzazione sopra monoscreen
				if ((Flags & WTF_OVER_BINOCULAR) == 0) break;

			}
			if (SkipFlags & SKIP_LASER_SIGHT) {
				// verificare se c'e' il flag che abuilita visualizzazione sopra monoscreen
				if ((Flags & WTF_OVER_LASER_SIGHT) == 0) break;

			}

			i = GlobTomb4.BaseParamWText.VetIds[pAzione->ItemIndex];
			pWText = &GlobTomb4.BaseParamWText.VetParamWText[i];

			i = GlobTomb4.BaseFonts.VetID[pWText->WindowsFontId];
			pFont = &GlobTomb4.BaseFonts.VetFonts[i];

			if (pAzione->Arg1 != SCRIPT_IGNORE) pAzione->Arg1--;
			if (pAzione->Arg1 == 0) {
				pAzione->ActionType=0;
				if (Flags & (WTF_FLYING_TEXT | WTF_PULSING_TEXT)) {
					// ripristinare dimensione del font
					pFont->SizeFont = pAzione->VetArg[0];
					if (pFont->hFont) {
						DeleteObject(pFont->hFont);
						pFont->hFont = NULL;
					}
				}
				if (Flags & WTF_CHANGE_COLOR) {
					// ripristinare colore originale di font
					pFont->ColoreText = pAzione->VetArgDword[0];
				}
				break;
			}


			pChar = GetStringaNG(pAzione->Arg2);
			

			
			// preparare rettangolo
			MioRect = pWText->MyRect;
			ConvertiRectMicroUnits(&MioRect);

			// vedere il tipo di effetto
			if (Flags & WTF_PULSING_TEXT) {
				// cambiare dimensione del font
				
				if (pAzione->VetArg[5]==0) {
					pAzione->VetArgFloat[1] += pAzione->VetArgFloat[4];
					pFont->SizeFont= (int) pAzione->VetArgFloat[1];
					if (pFont->hFont) {

						DeleteObject(pFont->hFont);
						pFont->hFont=NULL;
					}
					TestMod=false;

					// ora vedere se bisogna cambiare inversione della dimensione
					if (pAzione->VetArgFloat[4] > 0) {
						// si stava incrementando, se dimensione maggiore invertire
						if (pAzione->VetArgFloat[1] >= pAzione->VetArgFloat[3]) {
							pAzione->VetArgFloat[4] = -pAzione->VetArgFloat[4];
							pFont->SizeFont = (int) pAzione->VetArgFloat[3];
							TestMod=true;
						}
					}else {
						// si stava decrementando, se dimensione minore  invertire
						if (pAzione->VetArgFloat[1] <= pAzione->VetArgFloat[2]) {
							pAzione->VetArgFloat[4] = -pAzione->VetArgFloat[4];
							pFont->SizeFont= (int) pAzione->VetArgFloat[2];
							TestMod=true;
						}
					}

					if (TestMod==true) {
						pAzione->VetArg[5]= 16;
					}
				}else {
					// siamo in fase di attesa su dimensione massima o minima
					pAzione->VetArg[5]--;
				}
				

			}

			if (Flags & WTF_CHANGE_COLOR) {


				// modificare colori

				for (i=0;i<3;i++) {
					Valore= pAzione->VetArgBytes[4+i];

					Valore += pAzione->VetArgSignedBytes[8+i];
					if (pAzione->VetArgSignedBytes[8+i] > 0) {
						if (Valore >= pAzione->VetArgBytes[16+i]) 
									pAzione->VetArgSignedBytes[8+i] = -pAzione->VetArgSignedBytes[8+i];
						if (Valore > 255) Valore=255;

					}else {
						if (Valore <= pAzione->VetArgBytes[12+i]) 
									pAzione->VetArgSignedBytes[8+i] = -pAzione->VetArgSignedBytes[8+i];
						if (Valore < 0) Valore=0;
					}
					pAzione->VetArgBytes[4+i] = (BYTE) Valore;
				}

				pFont->ColoreText = pAzione->VetArgDword[1];


			}

			if (Flags & WTF_FLYING_TEXT) {
				// incrementare dimensione di font
				
				if (pAzione->VetArg[5]==0) {
				
					// fase di incremento
					pAzione->VetArgFloat[1] *= pAzione->VetArgFloat[3];
					pAzione->VetArgFloat[3] += pAzione->VetArgFloat[4];

					

					// se abbiamo superato dimensione massima, fermarsi ed entrare in nuova fase
					if (pAzione->VetArgFloat[1] >= pAzione->VetArgFloat[2]) {
						// iniziare fase 1 
						pFont->SizeFont = pAzione->VetArg[0];
						pAzione->VetArg[5]=1;
						
					}else {
						// se siamo ancora in fase 0, ripristinare tempo
						if (pAzione->Arg1 != SCRIPT_IGNORE) pAzione->Arg1++;
						// e impostare valore attuale di dimnesione font
						pFont->SizeFont = (int) pAzione->VetArgFloat[1];
						if (pFont->hFont) {

							DeleteObject(pFont->hFont);
							pFont->hFont=NULL;
						}


					}
				}
													
			}

			if (StampaWindowsText(pChar, &MioRect, pWText->WindowsFontId,pWText->Flags )==false) {
				pAzione->ActionType=0;
				if (Flags & (WTF_FLYING_TEXT | WTF_PULSING_TEXT)) {
					// ripristinare dimensione del font
					pFont->SizeFont = pAzione->VetArg[0];
					if (pFont->hFont) {
						DeleteObject(pFont->hFont);
						pFont->hFont = NULL;
					}
				}

				if (Flags & WTF_CHANGE_COLOR) {
					// ripristinare colore originale di font
					pFont->ColoreText = pAzione->VetArgDword[0];
				}
			}
			break;
	}



}

void EseguiAzioniWindowsFont(void)
{
	StrProgressiveAction *pAzione;
	int i;
	int OldAction;

	pAzione = &GlobTomb4.VetProgressiveActions[0];
	
	for (i=0;i<GlobTomb4.TotProgressiveActions;i++) {
		if (pAzione->ActionType) {
			OldAction = pAzione->ActionType;
			EsegueAzioneWindowsFont(pAzione);
			if (pAzione->ActionType == 0) {
				GestioneCompletedProgActions(OldAction, i);
			}
		}

		pAzione++;
	}


}

void EsegueAzioneTesto(StrProgressiveAction *pAzione)
{
	char *pChar;
	WORD *pValoreMaxFadeClip = (WORD*) 0x4BF25A;
	WORD *pValoreFadeClip = (WORD*) 0x4BF258;
	DWORD *pIndiceComandoAnimazione = (DWORD*) 0x4BFB4C;
	bool TestStampa;
	int i;
	int MaxSprite;
	int j;
	RECT *pRect;
	BYTE Opaco;
	short CordX,CordY;
	char *pTesto;
	int TestEsito;
	int SalvaCount;
	RECT MioRect;
	StrShowSprite *pSprite;
	int Indice;
	int x,y;
	RECT NewRect;
	int Incremento;

	Incremento = -1;
	if (GlobTomb4.TestAlreadyDisplayedStrings == true) Incremento=0;

	switch (pAzione->ActionType) {

	case AZ_SHOW_SPRITE:
		// mostra sprite
		if (pAzione->Arg2 ==0) {

			if (pAzione->Arg1 != SCRIPT_IGNORE) pAzione->Arg1 --;
			if (pAzione->Arg1 == 0) {
				pAzione->ActionType =0;
				break;
			}
		}
		// trovare dati sprite
		j = pAzione->ItemIndex;
		j = GlobTomb4.BaseShowSprites.VetIdShowSprites[j];

		if (j==-1) {
			sprintf(BufferLog, "ERROR: lost Parameters=PARAM_SHOW_SPRITE with id=%d while showing sprite",
				pAzione->ItemIndex);
			InviaLog(BufferLog);
			pAzione->ActionType=0;
			break;
		}

		pSprite = &GlobTomb4.BaseShowSprites.VetShowSprites[j];
		// se non ci sono effetti lavorare 
		// su rettangolo di posizione originale
		if (pAzione->Arg2 == 0) {
			MioRect = pSprite->Posizione;
			
		}else {
			// c'e' effetto in corso
			pAzione->Arg2--;
			if (pSprite->Flags & FSS_EFFECT_ZOOM) {
				CalcolaSpriteZoom(pAzione, pSprite,false);
				MioRect.left = Float2Int(pAzione->VetArgFloat[0]);
				MioRect.top = Float2Int(pAzione->VetArgFloat[1]);
				MioRect.right = Float2Int(pAzione->VetArgFloat[2]);
				MioRect.bottom = Float2Int(pAzione->VetArgFloat[3]);
				
			}
			if (pSprite->Flags & (FSS_EFFECT_FROM_BOTTOM | FSS_EFFECT_FROM_TOP |
					FSS_EFFECT_FROM_LEFT | FSS_EFFECT_FROM_RIGHT)) {
				// effetto di movimento
				pAzione->VetArgFloat[0] += pAzione->VetArgFloat[2];
				pAzione->VetArgFloat[1] += pAzione->VetArgFloat[3];
				MioRect.left = Float2Int(pAzione->VetArgFloat[0]);
				MioRect.top = Float2Int(pAzione->VetArgFloat[1]);
				MioRect.right = pSprite->Posizione.right;
				MioRect.bottom = pSprite->Posizione.bottom;
				
			}
		}

		pRect = &MioRect;
		// ora convertire questi valori in coordinate di schermo
		// e quindi mostrare lo sprite
		ConvertiSpriteMicroUnits(pRect);

		// calcolare se c'e' trasparenza
		if (pSprite->Flags & FSS_TRANSPARENT) {
			Opaco = 0x00;
		}else {
			Opaco= 0xff;
		}
		// visualizzare  griglia di sprite
		Indice = pSprite->IndiceSprite;
		// se animato gestire indice
		if (pSprite->Flags & FSS_ANIMATE) {
			Indice=pAzione->VetArgShort[11];
			// nota: se indice = vetargbytes[19] vuol dire che e' stato messo in pausa su quel frame
			if (Indice != pAzione->VetArgBytes[19]) {


				// vedere se bisogna cambiare indice per il prossimoframe
				pAzione->VetArgShort[10]--;
				MaxSprite = pSprite->IndiceSprite + (pSprite->ExtraValue & 0xff);

				if (pAzione->VetArgShort[10] == 0) {
					// bisogna cambiare indice sprite per prossima esecuzione
					pAzione->VetArgShort[10] = (pSprite->ExtraValue & 0xff00) >> 8;
					i = Indice;
					i += pAzione->VetArgSignedBytes[18];
					pAzione->VetArgShort[11]=i;
					// vedere se raggiunto il limite
					if (pAzione->VetArgSignedBytes[18] > 0) {
						// incremento positivo
						// vedere se raggiunto max
						if (i >= MaxSprite) {
							// si, raggiunto
							if (pSprite->Flags & FSS_ANIMATE_FOR_BACK) {
								pAzione->VetArgSignedBytes[18] = -1;
								pAzione->VetArgShort[11]= Indice-1;
							}else {
								pAzione->VetArgShort[11] = pSprite->IndiceSprite;
							}
						}

					}else {
						// incremento negativo
						if (i < pSprite->IndiceSprite) {
							// deve essere back for per forza
							pAzione->VetArgSignedBytes[18] = +1;
							pAzione->VetArgShort[11] = Indice+1;
						}


					}
						
				}
			}
		}
		if (pSprite->Flags & FSS_SHOW_SPRITE_GRID) {

			NewRect.right = pRect->right;
			NewRect.bottom = pRect->bottom;

			for (y=0;y<pSprite->GridY;y++) {
				for (x=0;x<pSprite->GridX;x++) {
					NewRect.left = pRect->left + pRect->right * x;
					NewRect.top = pRect->top + pRect->bottom * y;

					MostraSprite2d(&NewRect, pSprite->SlotSprite, 
											Indice, 
											Opaco, pSprite->Colore);
					if ((pSprite->Flags & FSS_CLONE_SPRITE)==0) Indice++;
				}
			}

		}else {
			// visualizza singolo sprite
			MostraSprite2d(pRect, pSprite->SlotSprite, 
					Indice, Opaco, pSprite->Colore);
		}
		break;

	case AZ_SHOW_CUSTOM_BAR:
		if (pAzione->Arg1 != 0xffff) pAzione->Arg1--;

		if (pAzione->Arg1 == 0) {

			// terminata
			pAzione->ActionType=0;
			break;
		}
		ShowBarraCustom(pAzione->ItemIndex);

		break;
	case AZ_PRINT_STRING:
	case AZ_SHOW_TIMER_TRNG:

		TestEsito =0;



		TestStampa=true;
		// visualizza stringa
		if (pAzione->Arg1 != 0xffff)  {
			pAzione->Arg1 += Incremento;
		}

		if (pAzione->Arg1 == 0) {
			// terminato tempo di visualizzazione stringa
			pAzione->ActionType = 0;
			TestStampa=false;
			
		}

		if (TestStampa==true) {
			CordX = pAzione->VetArg[4];
			CordY = pAzione->VetArg[5];
			FlagMicroCaratteri = (BYTE) pAzione->Arg2;
			// disattivare visualizzazione timer se concse
			if (GlobTomb4.pDiagnostica->DgxExtra & EDGX_CONCISE_SCRIPT_LOG) {
				SalvaCount = GlobTomb4.DebugModeCounter;
				GlobTomb4.DebugModeCounter=0;
			}
			pChar = ReplaceVarPlaceFolders((char *) pAzione->VetArg[0]);
			if (GlobTomb4.pDiagnostica->DgxExtra & EDGX_CONCISE_SCRIPT_LOG) {

				GlobTomb4.DebugModeCounter=SalvaCount;
			}


			PrintString(CordX,CordY, pAzione->VetArgWord[4], 
					pChar, pAzione->VetArg[1]);
			FlagMicroCaratteri = GlobTomb4.PrintString.DefALLFlagsMicro;

		}
		
		break;
	case AZ_SCROLLING_VTEXT:
		// scrolling text
		// eseguire scrolling
		// aggiornare posizione

		pAzione->VetArgFloat[5] -= pAzione->VetArgFloat[4];
		// ora costruire coordinate x, y
		if (pAzione->VetArgShort[5] == -1) {
			CordX = *GlobTomb4.pAdr->pSizeScreenX / 2;
		}else {
			CordX = pAzione->VetArgShort[5];
		}
		// per debug, provare a non usare arrtondamento


		CordY = (short) pAzione->VetArgFloat[5];


		// altrimenti mostrare in posizione attuale
		AggiornaAdrStringa(pAzione);
		// aggiungere offset attuale
		pTesto = (char*) pAzione->VetArg[0];
		pTesto = &pTesto[pAzione->VetArgShort[6]];


		FlagMicroCaratteri = (BYTE) pAzione->Arg2;
		pChar = ReplaceVarPlaceFolders(pTesto);
		PrintString(CordX,CordY, pAzione->VetArgWord[4], 
			pChar, pAzione->VetArg[1]);
		FlagMicroCaratteri = GlobTomb4.PrintString.DefALLFlagsMicro;

		if (RobaScrolling.TestLastVisible == true) {
			// rilevare attivazione
			GlobTomb4.ScrollingLastIndex = pAzione->ItemIndex & 0x7fff;
		}

		// ok,ora vedere se abbiamo finito
		// e in caso contrario aggiornare offset
		if (CordY < 0 && RobaScrolling.RigaInizio.TextOffset == -1) {

			// salvare indice semplice di stringa per 
			// rilevare global trigger
			GlobTomb4.ScrollingEndIndex= pAzione->ItemIndex & 0x7fff;
			GlobTomb4.ScrollingLastIndex=-1;
			pAzione->ActionType=0;
			break;
		}
		// non e' finita
		// vedere se bisogna aggiornare offset
		if (RobaScrolling.RigaInizio.TextOffset != -1 &&
			RobaScrolling.RigaInizio.TextOffset != 0) {
			// adattare offset realtivo trovato da PrintString
			// con offset assoluto

			// si, ora devo cambiare sia offset che cordy
			pAzione->VetArgShort[6] += RobaScrolling.RigaInizio.TextOffset;
			pAzione->VetArgFloat[5] = (float) RobaScrolling.RigaInizio.OrgY;



		}

		break;
	case AZ_SCROLLING_HTEXT:
		// scrolling text
		// eseguire scrolling
		// aggiornare posizione

		pAzione->VetArgFloat[5] -= pAzione->VetArgFloat[4];
		// ora costruire coordinate x, y

		CordX = Float2Int(pAzione->VetArgFloat[5]);
		CordY = pAzione->VetArgShort[5];

		// altrimenti mostrare in posizione attuale
		AggiornaAdrStringa(pAzione);
		// aggiungere offset attuale
		pTesto = (char*) pAzione->VetArg[0];
		pTesto = &pTesto[pAzione->VetArgShort[6]];


		FlagMicroCaratteri = (BYTE) pAzione->Arg2;
		pChar = ReplaceVarPlaceFolders(pTesto);
		PrintString(CordX,CordY, pAzione->VetArgWord[4], 
			pChar, pAzione->VetArg[1]);
		FlagMicroCaratteri = GlobTomb4.PrintString.DefALLFlagsMicro;



		// ok,ora vedere se abbiamo finito
		// e in caso contrario aggiornare offset
		if (CordX < 0 && RobaScrolling.LastCordX < RobaScrolling.LarghezzaCar ) {
			// terminato
			pAzione->ActionType=0;
			break;
		}
		// non e' finita
		// vedere se bisogna aggiornare offset
		if (RobaScrolling.PosizioneInizio.OffsetH   != -1 &&
			RobaScrolling.PosizioneInizio.OffsetH  != 0) {
			// adattare offset realtivo trovato da PrintString
			// con offset assoluto

			// si, ora devo cambiare sia offset che cordx
			pAzione->VetArgShort[6] += 
					RobaScrolling.PosizioneInizio.OffsetH;
			pAzione->VetArgFloat[5] = 
					(float) RobaScrolling.PosizioneInizio.OrgX;
		}

		break;
	}	
}
// esegue azioni che richiedono di esswere eseguite al di fuori di drawphasegame
// come avvine per la visualizzazione delle stringhe di testo
// nota: NON ridurre numero frames (per durata stringa) se GlobTomb4.TestAlreadyDisplayedStrings == true
//			perche' signfiica che era gia stata visualizza in altri punti del codice
void EseguiAzioniTesto(void)
{
	StrProgressiveAction *pAzione;
	char *pChar;
	WORD *pValoreMaxFadeClip = (WORD*) 0x4BF25A;
	WORD *pValoreFadeClip = (WORD*) 0x4BF258;
	DWORD *pIndiceComandoAnimazione = (DWORD*) 0x4BFB4C;
	short CordX,CordY;
	int z;
	int OldAction;


	//PreparaTestoAmmoCounter
	// non stamparla se non ci sono le giuste 
	// condizioni particolari

	if (GlobTomb4.pBaseCustomize->TestPrintOnFlyby == false) {
		if (*pValoreMaxFadeClip || *pValoreFadeClip || 
					*pIndiceComandoAnimazione) return;
	}



#ifdef LOG_CRYPT
	
	MostraTestoAvvisoCrypt();
	
#endif
	if (GlobTomb4.ScriptOptions.MainFlags & ngfm_Diagnostica) 
			DiagnosticaOnScreen();



	pAzione= &GlobTomb4.VetProgressiveActions[0];

	for (z=0;z<GlobTomb4.TotProgressiveActions;z++) {
		switch (pAzione->ActionType) {
		case AZ_SHOW_SPRITE:
		case AZ_SHOW_CUSTOM_BAR:
		case AZ_PRINT_STRING:
		case AZ_SHOW_TIMER_TRNG:
		case AZ_SCROLLING_VTEXT:
		case AZ_SCROLLING_HTEXT:


			OldAction = pAzione->ActionType;
			EsegueAzioneTesto(pAzione);
			if (pAzione->ActionType == 0) {
				GestioneCompletedProgActions(OldAction, z);
			}
			break;
		}

		pAzione++;
			
	}

	if (GlobTomb4.pAdr->pLara->AnimationNow == 462 &&
		*GlobTomb4.pAdr->pTestFlybyInProgress == 0 && 
		(GlobTomb4.ParallelBar.ParallelBarFlags & PB_SHOW_CHARGE_COUNTER) != 0) {

		ShowChargeCounter();
	}

	if (*GlobTomb4.pAdr->pTestFlybyInProgress == 0 &&  
				PreparaTestoAmmoCounter()) {
		pAzione= &GlobTomb4.pBaseCustomize->ShowAmmoCounter.AzioneTestoCounter;

		CordX = pAzione->VetArg[4];
		CordY = pAzione->VetArg[5];
		FlagMicroCaratteri = (BYTE) pAzione->Arg2;
		pChar = ReplaceVarPlaceFolders((char *) pAzione->VetArg[0]);
		PrintString(CordX,CordY, pAzione->VetArgWord[4], 
			pChar, pAzione->VetArg[1]);
		FlagMicroCaratteri = GlobTomb4.PrintString.DefALLFlagsMicro;
	}
		
}

// per colore:
// arancio=0xfffb8953;	Rosa= 0xfff924f1;
// giallo=0xFFF6F923
void ShowBarraDamage(int Percentuale, DWORD Colore, bool TestColdWater)
{

	int CordX, CordY;
	WORD Altezza;
	DWORD ColoreFade;
	StrBarraCust *pBar;

	
	Altezza = *GlobTomb4.pAdr->pRowCharHeight;

	if (TestColdWater == true) {
		pBar= &GlobTomb4.pBaseCustomize->VetBar[BAR_COLD];
		if (pBar->OrgX == -1 || pBar->OrgY == -1) {
			// metterla sotto barra respiro

			CordX = 0x1EA - Altezza/4;
			CordY =45;
		}else {
			CordX = pBar->OrgX;
			CordY = pBar->OrgY;
		}
	}else {
		pBar= &GlobTomb4.pBaseCustomize->VetBar[BAR_DAMAGE];
		if (pBar->OrgX == -1 || pBar->OrgY == -1) {
			// metterla sotto hp bar
			CordX = Altezza/4;
			CordY = 30;
		}else {
			CordX = pBar->OrgX;
			CordY = pBar->OrgY;
		}


	}

	ColoreFade = pBar->Color2; 
	if (TestColdWater==true) {
		if (pBar->Color1 != 0xfff924f1) Colore=pBar->Color1;
	}else {
		if (pBar->Color1 != 0xffF6F923) Colore=pBar->Color1;
	}
	CordY = AdattaCordY(CordY);
	if (pBar->Flags & FBAR_SOUND_BAR_ANIM) {
		//     (int OrgX, int OrgY, int SizeX, int SizeY, int Volume, DWORD BackColor, DWORD MainColor, DWORD MaskColor);
		DoSlider(CordX, CordY, pBar->SizeX, pBar->SizeY, Percentuale, ColoreFade, Colore, pBar->ExtraLong);
	}else {
		DoBar(CordX,CordY, pBar->SizeX , pBar->SizeY , Percentuale, ColoreFade, Colore );
	}
}

// visualizza la barra custom  CustomType (BAR_CUSTOM1/2/3/4) sullo schermo
void ShowBarraCustom(int CustomType)
{
	StrBarraCust *pBar;
	int Valore;
	int IndiceNG;
	int CordX, CordY;
	char *pChar;
	float Size;


	pBar = &GlobTomb4.pBaseCustomize->VetBar[CustomType];

	if (pBar->Flags & FBAR_USED_FOR_BOAT_FUEL) {
		Valore = LeggiVariabile(0x72);
		if (Valore > (int) pBar->ExtraLong) {

			Valore= pBar->ExtraLong;
			ScriviVariabile(0x72, Valore);
		}

		// costruire rapporto sulla base di max fuel
		Valore = (Valore * 100) / pBar->ExtraLong;



	}else {
		Valore = LeggiVariabile(pBar->Extra);
	}

	if (Valore > 100) Valore=100;

	if (Valore < 0) Valore=0;
	CordX = pBar->OrgX + 2;
	CordY = pBar->OrgY + 2;

	CordY = AdattaCordY(CordY);

	if (pBar->Flags & FBAR_SOUND_BAR_ANIM) {
		//     (int OrgX, int OrgY, int SizeX, int SizeY, int Volume, DWORD BackColor, DWORD MainColor, DWORD MaskColor);
		DoSlider(CordX, CordY, pBar->SizeX, pBar->SizeY, Valore, pBar->Color1 , pBar->Color2 , pBar->ExtraLong);
	}else {
		DoBar(CordX, CordY, pBar->SizeX, pBar->SizeY, Valore, pBar->Color1, pBar->Color2);
	}


	

	if (pBar->Flags & FBAR_SHOW_BAR_NAME) {


		CordX = pBar->OrgX;
		CordY = pBar->OrgY + pBar->SizeY;
		CordY = pBar->OrgY;

		ConvertiCordScreen(&CordX, &CordY);
		CordX += 1;

		Size = (float) *GlobTomb4.pAdr->pRowCharHeight;
		Size *= 0.7f;

		CordY += Float2Int(Size);
		IndiceNG = 301 - 4 + CustomType;
		pChar = GetStringaNG(IndiceNG);

		if (pChar) {


			pChar = ReplaceVarPlaceFolders(pChar);
			FlagMicroCaratteri= FT_SIZE_ATOMIC_CHAR;

			PrintString(CordX,CordY, FC_WHITE,	pChar, 0);

			FlagMicroCaratteri = GlobTomb4.PrintString.DefALLFlagsMicro;
		}
	}
	
}
// mostra barra piccolina per monitorare 
void ShowBarraPerParallele(void)
{
	int Percentuale;
	WORD Altezza;
	int CordY;


	Altezza = *GlobTomb4.pAdr->pRowCharHeight;

	Percentuale = (GlobTomb4.ParallelBar.TotFrames * 100) / 
						(GlobTomb4.pBaseCustomize->ParallelMaxTurns << 5);
	if (Percentuale > 100) Percentuale=100;

	CordY = (int) RapportoFloatSchermo(*GlobTomb4.pAdr->pSizeScreenY, 
					(float) 480, 440);
	DoBar(300,CordY , 40, 12, Percentuale, 0xff000000,0xff00ff00);
	

	
}

void ShowChargeCounter(void)
{
	int CordX;
	int CordY;
	char *pChar;
	StrProgressiveAction ActionType;

	CordX = (int) RapportoFloatSchermo(*GlobTomb4.pAdr->pSizeScreenX, 
					(float) 640, 300);

	CordY = (int) RapportoFloatSchermo(*GlobTomb4.pAdr->pSizeScreenY, 
					(float) 480, 465);

	ActionType.ItemIndex = 220;
	AggiornaAdrStringa(&ActionType);
	pChar = (char *) ActionType.VetArg[0];
	sprintf(BufferLog,pChar, GlobTomb4.ParallelBar.GiriCompleti);


	StampaStringa(*GlobTomb4.pAdr->pSizeScreenX / 2 , CordY, BufferLog, 
			FT_LITTLE_ALWAYS, FC_WHITE, FTS_ALIGN_CENTER );
}

// verifica se mostrare una barra extra per damage o water cold o fuel boat
void MostraBarraExtra(void)
{
	StrDamage *pRec;
	int i;
	DWORD Colore;
	StrItemTr4 *pItem;
	bool TestShowFuel;


	if (*GlobTomb4.pAdr->pFlagsLara & 0x08) return;
	pRec = & GlobTomb4.DamageColdWater;

	if ((pRec->FlagProgresso & FPD_ATTIVO) ||
		(GlobTomb4.pBaseCustomize->VetBar[BAR_COLD].Flags & FBAR_DRAW_ALWAYS)){

		Colore=pRec->Colore;
		if (pRec->FlagProgresso & FDP_BLINK_SHOW_ORA) 
			Colore ^= 0xffffff;
	
		ShowBarraDamage(pRec->Percentuale, Colore,true);
	}

	pRec = &GlobTomb4.DamageRoom;
	if ((pRec->FlagProgresso & FPD_ATTIVO)|| 
		(GlobTomb4.pBaseCustomize->VetBar[BAR_DAMAGE].Flags & FBAR_DRAW_ALWAYS)){

		Colore=pRec->Colore;
		if (pRec->FlagProgresso & FDP_BLINK_SHOW_ORA) 
			Colore ^= 0xffffff;		
		ShowBarraDamage(pRec->Percentuale, Colore,false);
	}

	if (GlobTomb4.ParallelBar.TestMostraBarra) {
		ShowBarraPerParallele();

	}

	// vedere se lara e' su una barca che ha la gestione del carburante e la visualizzazione della barra
	TestShowFuel=false;
	i = *GlobTomb4.pAdr->pVehicleIndex;
	if (i != -1) {
		pItem = &GlobTomb4.pAdr->pVetItems[i];

		if (pItem->SlotID  == GlobTomb4.BaseIndiciNew.IndiceMotorBoat  || 
			pItem->SlotID  == GlobTomb4.BaseIndiciNew.IndiceRubberBoat) {

			if ((pItem->OcbCode & 0xA0)==0xA0) TestShowFuel=true;
		}
	}

	if (TestShowFuel) ShowBarraCustom(BAR_CUSTOM4);


}

