// aggiornare frame e animazione di target attuale
void AggiornaAnimazioneTarget(StrTargetDetector *pTarget)
{
	if (pTarget->Fase == FTR_INATTIVO) return;

	pTarget->DurataTotale --;
	if (pTarget->DurataTotale <= 0) {
		pTarget->Fase = FTR_INATTIVO;
		return;
	}
	pTarget->DurataFase --;
	if (pTarget->DurataFase > 0) return;

	// bisogna cambiare qualcosa.
	switch (pTarget->Fase) {
	case FTR_NASCITA:
		// incrementa frame e quando si arriva a frame 4 passare
		// a fase lampeggio e scegliere il frame a seconda 
		// di PosY sopra, sotto o uguale

		if (pTarget->Frame == 0) {
			// fare beep
			SoundEffect(GlobTomb4.Suoni.DetectorBeep , NULL, 2);
		}
		pTarget->Frame++;

		if (pTarget->Frame >= 4) {
			// terminata fase nascita, iniziare fase lampeggio
			pTarget->Fase = FTR_LAMPEGGIO;
			pTarget->Incremento=1;
			switch (pTarget->VPos) {
			case PTR_BASE_LARA:
				// stessa altezza di lara, usare frame tondo
				// che dura 8 frame
				pTarget->DurataFase = DTAR_LAMPEGGIO_TONDO;
				pTarget->Frame = 4;
				pTarget->Incremento =1;
				break;
			case PTR_SOTTO_LARA:
				// oggetto e' sotto
				pTarget->DurataFase = DTAR_LAMPEGGIO_TRIANGOLO;
				
				pTarget->Frame = 10;
				break;
			case PTR_SOPRA_LARA:
				// oggetto e' sopra
				pTarget->DurataFase = DTAR_LAMPEGGIO_TRIANGOLO;
				pTarget->Frame = 8;
				break;
			}
				

			break;
		}
		pTarget->DurataFase = DTAR_NASCITA;
		break;
	case FTR_LAMPEGGIO:
		// calcoli diversi a seconda di tipo di lampeggio per tondo
		// o per triangolo

		switch (pTarget->VPos) {
		case PTR_BASE_LARA:
			// altezza di lara, tondo frame 4, 5, 6, 7 da percorrere
			// avanti e indietro
			// vedere se bisogna invertire direzione di incremento
			switch (pTarget->Frame) {
			case 4:
				pTarget->Incremento=1;
				break;
			case 7:
				pTarget->Incremento=-1;
				break;
			}

			pTarget->Frame += pTarget->Incremento;
			pTarget->DurataFase = DTAR_LAMPEGGIO_TONDO;
			break;
		case PTR_SOPRA_LARA:
		case PTR_SOTTO_LARA:
			// oggetto triangolo sopra, frame 8, 9
			// oggetto triangolo sotto, frame 10, 11
			// per entrambi basta invertire bit di valore 1 
			pTarget->Frame ^= 1;
			pTarget->DurataFase = DTAR_LAMPEGGIO_TRIANGOLO;
			break;
		}

	}


}






DWORD FindSkipPhase(void)
{
	DWORD FlagsSkip;


	FlagsSkip= SKIP_NONE;

	if (*GlobTomb4.pAdr->pFadeScreen) FlagsSkip |= SKIP_FADE;

	if (*GlobTomb4.pAdr->pTestLoading) FlagsSkip |= SKIP_LOADING_LEVEL;
  
	if (*GlobTomb4.pAdr->Camera.pModeCameraNow  == 1) FlagsSkip |= SKIP_FIXED_CAMERA;	

	if (*GlobTomb4.pAdr->pTestFlybyInProgress) FlagsSkip |= SKIP_FLY_CAMERA;

	if (*GlobTomb4.pAdr->pLevelNow == 0 &&
		(*GlobTomb4.pAdr->pScriptMainFlags & 0x04)) FlagsSkip |= SKIP_TITLE_LEVEL;

	if (*GlobTomb4.pAdr->pTestGrayScreen) FlagsSkip |= SKIP_GRAY_SCREEN;

	if (GlobTomb4.TestSuspendObjectShowing == true) FlagsSkip |= SKIP_NO_VIEW_OGGETTI;

	if (*GlobTomb4.pAdr->pZoomFactor != 0 && *GlobTomb4.pAdr->pTestLaserSight ==0) FlagsSkip |= SKIP_BINOCULARS;

	if (*GlobTomb4.pAdr->pTestLaserSight && (*GlobTomb4.pAdr->pInputExtGameCommands & 0x200) != 0) FlagsSkip |= SKIP_LASER_SIGHT;

	if (GlobTomb4.TestOverlapImage==true) FlagsSkip |= SKIP_FULL_IMAGE;
	return FlagsSkip;

}
