// esegue animazione di texture uvrotate e frame
void PatchAnimTextures(int ValoreSync)
{
	int i;
	int Cicli;

	StrAnimFrame *pAnimRange;
	StrTexInfoTr4 SalvaTex;
	bool TestEsegui;
	DWORD TempoNow;
	int Indice;
	int SalvaIndice;
	int IndiceNow;
	int *pContatoreCicliFrame = (int*) 0x5C0348;
	int NumTex;
	int UVRotate;
	StrAnimUVRotate *pAnimRotate;
	int j,z;
	float FloatPos;
	float OrgY;
	float DifY;

	float *pVertici;
	DWORD TickNow;


		
	(*pContatoreCicliFrame) += ValoreSync;

	Cicli=0;

	TickNow = GetTickCount();


	while (*pContatoreCicliFrame > 5) {
		pAnimRange = &GlobTomb4.BaseAnimTr4.VetFrameRanges[0];
		for (i=0;i<GlobTomb4.BaseAnimTr4.TotFrameRanges;i++) {
			// vedere se questo range va eseguito
			TestEsegui=true;

			if (pAnimRange->TestStop) TestEsegui=false;
			// non eseguirlo se e' un ciclo diverso da primo
			// e se c'e' un tempo da controllare, perche' in questo
			// caso e' gia' stasto eseguito nel primo ciclo
			if (Cicli && pAnimRange->DelayTime) TestEsegui=false;
			
			// fare controllo per tempo
			if (TestEsegui && pAnimRange->DelayTime) {
				TempoNow = TickNow - pAnimRange->LastTime;
				if (TempoNow < pAnimRange->DelayTime ) TestEsegui=false;
				
			}
			if (TestEsegui) {
				pAnimRange->LastTime = TickNow;
				// eseguire 
				// codice diverso a seconda se e' P-frame
				if (pAnimRange->TipoAnim == FAN_P_FRAMES) {

					// copiare il frame impostato nell'indice previsto
					IndiceNow = pAnimRange->FrameToSet;

					Indice = pAnimRange->VetTailIndex[pAnimRange->IndiceToSet];

					GlobTomb4.pAdr->VetTexInfo[Indice] = 
							pAnimRange->VetTexInfoRecords[IndiceNow];
					// aggiornare l'indice di ogni tex visualizzata
					// per ogni frame
					pAnimRange->VetChangedPos[pAnimRange->IndiceToSet] = IndiceNow; 

#ifdef DEBUG_ON
					sprintf(BufferLog, "Cambiato valore VetChangedPos[%d]=%d (Indice=%d  IndiceNG=%d)",
						pAnimRange->IndiceToSet, 
						IndiceNow, i, pAnimRange->IndiceRangeNG );
					InviaLog(BufferLog);

#endif


					
					// fermare aggioramento poiche' rimane uguale
					// finche' un flipeffect non richiede un cambio di frame
					pAnimRange->TestStop=true;
				}else {
					// e' un frame normale
					// effettuare rotazione di tutti i record texinfo 
					// relativi
					NumTex = pAnimRange->TotTextures;

					SalvaTex = GlobTomb4.pAdr->VetTexInfo[pAnimRange->VetTailIndex [0]];


					for (j=0;j< (NumTex-1);j++) {
						Indice = pAnimRange->VetTailIndex[j];

						GlobTomb4.pAdr->VetTexInfo[Indice] = 
								GlobTomb4.pAdr->
									VetTexInfo[pAnimRange->VetTailIndex[j+1]];


					}

					GlobTomb4.pAdr->VetTexInfo[pAnimRange->VetTailIndex[j]] = 
								SalvaTex;

					// se questo frame fa parte di river, ruotare
					// ache le texture nel record scroll associato
					if (pAnimRange->IndiceScrollRiver != -1) {

						pAnimRotate = &GlobTomb4.BaseAnimTr4.VetUVRanges[
								pAnimRange->IndiceScrollRiver];
						NumTex = pAnimRotate->TotTextures;
						SalvaIndice = pAnimRotate->VetTailIndex[0];


						for (j=0;j< (NumTex-1);j++) {
							pAnimRotate->VetTailIndex[j] =
								pAnimRotate->VetTailIndex[j+1];

						}
						pAnimRotate->VetTailIndex[j] = SalvaIndice;


					}


				}

			}

			pAnimRange++;	
		}
		Cicli++;

		(*pContatoreCicliFrame) -= 5;
	}

	pAnimRotate = &GlobTomb4.BaseAnimTr4.VetUVRanges[0];

	// ok ora animare uv rotate
	for (i=0;i<GlobTomb4.BaseAnimTr4.TotUvRanges;i++) {
		TestEsegui=true;
		if (pAnimRotate->TestStop) {
			TestEsegui=false;
		}else {
			if (pAnimRotate->DelayTime) {
				TempoNow = TickNow - pAnimRotate->LastTime;

				if (TempoNow < pAnimRotate->DelayTime ) 
						TestEsegui=false;


			}
		}
	

		if (TestEsegui) {
			pAnimRotate->LastTime =TickNow;
			if (pAnimRotate->TipoAnim & 1) 
				// questo era l'originale 
				UVRotate = pAnimRotate->UvRotate * (ValoreSync / 2);
			else
				UVRotate = pAnimRotate->UvRotate;

			pAnimRotate->ScrollPos -= UVRotate;
			pAnimRotate->ScrollPos &= pAnimRotate->Maschera;
			FloatPos = IntCord2Float( pAnimRotate->ScrollPos);
			
			// ora modificare tutte le texture di questo range
			if (pAnimRotate->TestTriangolo==true) {
				// per triangolo c'e' un calcolo particolare
				for (j=0;j<pAnimRotate->TotTextures;j++) {
					// calcolare la DifY da applicare ad ogni cordy
					// del triangolo
					Indice = pAnimRotate->VetTailIndex[j];
					OrgY = pAnimRotate->VetOrgY[j] + FloatPos;
					// ora vedere differenza
					pVertici =  &GlobTomb4.pAdr->VetTexInfo[Indice].TopLeft[0];

					DifY = OrgY - pVertici[pAnimRotate->IndiceVerticeTop];
					// adesso aggiungere DifY a tutti e 3 i vertici y
					for (z=1;z<8;z+=2) {
						pVertici[z] += DifY;
					}

				}

			}else {
				// per texture quadrate e' piu' facile
				
				for (j=0;j<pAnimRotate->TotTextures;j++) {

					Indice = pAnimRotate->VetTailIndex[j];
					OrgY = pAnimRotate->VetOrgY[j] + FloatPos;

					GlobTomb4.pAdr->VetTexInfo[Indice].TopLeft[1] = OrgY;
					GlobTomb4.pAdr->VetTexInfo[Indice].TopRight[1] = OrgY;
					OrgY += pAnimRotate->Height;
					GlobTomb4.pAdr->VetTexInfo[Indice].BottomLeft[1] = OrgY;
					GlobTomb4.pAdr->VetTexInfo[Indice].BottomRight[1] = OrgY;

				}
				

				
			}
		}
		pAnimRotate++;
	}



}


