// quando e' presente immagine per title viene allocata solo una volta all'inizio
// verra' poi rilasciata alla fine di tutto.
void AllocaTitleImage(void)
{
	StrBaseImgBackGround *pTitle;
	StrShowImage *pBase;
	BLENDFUNCTION Blend;

	pTitle = &GlobTomb4.BaseImgTitle;

	if (pTitle->TestEnabled==false) return;
	if (pTitle->TestAllocatedImage == true) return;
	InviaLog("Allocate Title Image");
	pBase = &GlobTomb4.BaseImages;

	if (AllocaHdcTomb(pBase, true, false)==false) {
		pTitle->TestEnabled=false;
		return;
	}

	if ((pTitle->Flags & BKGDF_KEEP_GAME_SCREEN)==0) {


		if (AllocaImmagine(pTitle->ImageNumber, &pBase->ImageTitle,-1,-1)==false) {
			pTitle->TestEnabled=false;
			LiberaHdcTomb(pBase, false);
			return;
		}


		SetStretchBltMode(pBase->Temp.MemHdc, COLORONCOLOR);



		// ora ridimensionare e copiare immagine title in temphdc con dimensione uguali a quelle di tomb
		StretchBlt(pBase->Temp.MemHdc, 
			0, 0,
			pBase->ZonaSchermoTomb.right, pBase->ZonaSchermoTomb.bottom ,
			pBase->ImageTitle.MemHdc , 
			0,0,
			pBase->ImageTitle.SizeX,
			pBase->ImageTitle.SizeY, SRCCOPY);
		// ora liberare title perche' poi usero' title con immagine di temp
		LiberaImmagine(&pBase->ImageTitle);

	}else {
		// c'e' flag BKGDF_KEEP_GAME_SCREEN
		if (pTitle->Flags & BKGDF_SEMI_TRANSPARENT) {
			// allocare immagine e copiarla con effetto trasparenza su quella temp
			if (AllocaImmagine(pTitle->ImageNumber , &pBase->ImageTitle, -1,-1)==false) {
				InviaLog("ERROR: Failed loading image for BKGDT_TITLE of CUST_BACKGROUND command");

				return;
			}
			Blend.AlphaFormat = 0; // 1= valore di AC_SRC_ALPHA;
			Blend.BlendFlags = 0;
			Blend.BlendOp = AC_SRC_OVER;
			Blend.SourceConstantAlpha = (BYTE) pTitle->Parameter;  // livello trasparenza 0=trasparenza / 255=opaco

			AlphaBlend(pBase->Temp.MemHdc, 0,0, pBase->Temp.SizeX, pBase->Temp.SizeY, 
				pBase->ImageTitle.MemHdc, 0,0, pBase->ImageTitle.SizeX, pBase->ImageTitle.SizeY, Blend);
			LiberaImmagine(&pBase->ImageTitle);

		}
	}

	pTitle->TestAllocatedImage=true;
	InviaLog("Save in TitleImage the image from temp hdc");
	// adesso traferire dati di temp hdc in title
	pBase->ImageTitle = pBase->Temp;
	// ora segnalare temp come gia' liberato
	memset(&pBase->Temp, 0, sizeof(StrRecordImage));

	LiberaHdcTomb(&GlobTomb4.BaseImages, false);


}
void RefreshTitleImage(void)
{
	
	StrBaseImgBackGround *pTitle;
	StrShowImage *pBase;
	BOOL TestEsito;
	SalvaSliderInput *pSlider;

	pTitle = &GlobTomb4.BaseImgTitle;

	if (pTitle->TestEnabled == false || pTitle->TestAllocatedImage==false) return;
	if (*GlobTomb4.pAdr->pLevelNow != 0) return;


	pBase = &GlobTomb4.BaseImages;

	// ok, visualizzare immagine
	if (AllocaHdcTomb(pBase, false, true)==false) {
		pTitle->TestEnabled=false;
		return;
	}
	// incomnciamo copiando il background sullo schermo temp
	SetStretchBltMode(pBase->HdcTomb , COLORONCOLOR);

	if (pTitle->TestTransparent) {
		TestEsito=TransparentBlt(pBase->HdcTomb  , 
			0, 0,
			pBase->ZonaSchermoTomb.right, 
			pBase->ZonaSchermoTomb.bottom ,
			pBase->ImageTitle.MemHdc , 
			0,0,
			pBase->ImageTitle.SizeX,
			pBase->ImageTitle.SizeY, 0xff00ff);		
	}else {
		TestEsito=BitBlt(pBase->HdcTomb  , 
			0, 0,
			pBase->ZonaSchermoTomb.right, pBase->ZonaSchermoTomb.bottom ,
			pBase->ImageTitle.MemHdc , 
			0,0, SRCCOPY);	

	}
	if (TestEsito==FALSE) {
		InviaLog("Error in bitblt operation");
	}
	LiberaHdcTomb(pBase,false);

	// se c'erano slider, visualizzarli adesso
	pSlider = &GlobTomb4.SliderMusic;
	if (pSlider->TestUsed) {
		InitShowOggetto();
		DoSlider(pSlider->Parameters[0], pSlider->Parameters[1], pSlider->Parameters[2], pSlider->Parameters[3], 
			pSlider->Parameters[4], pSlider->Parameters[5], pSlider->Parameters[6], pSlider->Parameters[7]);
		pSlider->TestUsed=false;
		EndShowOggetto();
	}
	pSlider = &GlobTomb4.SliderSfx;

	if (pSlider->TestUsed) {
		InitShowOggetto();
		DoSlider(pSlider->Parameters[0], pSlider->Parameters[1], pSlider->Parameters[2], pSlider->Parameters[3], 
			pSlider->Parameters[4], pSlider->Parameters[5], pSlider->Parameters[6], pSlider->Parameters[7]);
		pSlider->TestUsed=false;
		EndShowOggetto();
	}

}
// chiamata subito dopo aver caricato livello (e/o savegame)
// usata per inizializzare alcuni global trigger
void PreparaGlobalTriggers(void)
{

	// se = 4 allora e' stato caricato un savegame
	if (*GlobTomb4.pAdr->pTestLoadOrNewLevel ==4) {
		GlobTomb4.pBaseGlobalTriggers->TestCaricatoSavegame =true;
	}else {
		GlobTomb4.pBaseGlobalTriggers->TestCaricatoSavegame=false;
	}
		
}

// chiamata un attimo prima di salvare il savegame
void PrimaSalvaSaveGame(short IndiceSavegame)
{



	
	// vedere se e' un trigger globale per il salvataggio del savegame
	VerificaSingleGlobalTrigger(GT_SAVED_SAVEGAME, -1, true);
	// se c'e' standby attivo lo disattiva
	if (GlobTomb4.BaseStandBy.TestIniziato) TerminaStandBy(&GlobTomb4.BaseStandBy);

	// ripristina evenmtuale traccia audio originale
	if (GlobTomb4.AudioSospeso.CountSuspend ) {
		// scrivere i vecchi valori e poi ripristinarli al termine di salvataggio


		*GlobTomb4.pAdr->pCDTrackNow  = GlobTomb4.AudioSospeso.VetSospeso[0].NumeroCD ;
		*GlobTomb4.pAdr->pTestCdLoop  = GlobTomb4.AudioSospeso.VetSospeso[0].TestLoop;
		*GlobTomb4.pAdr->pAudioTrackLoop= GlobTomb4.AudioSospeso.VetSospeso[0].NumeroCD ;


	}


}
// chiamata per ogni moveable che si trova nella stanza flippata 
// che sta per essere rimossa
void AnalisiOggettoRimosso(StrItemTr4 *pItem, WORD ItemIndex)
{
	WORD Slot;
	int Altezza;

	Slot = pItem->SlotID;

	// vedere se e' un pushable
	if (Slot < 156 || Slot > 160) return;
	// ok e' un pushable
	// se risulta presente una collisione la toglie

	if (GlobTomb4.BasePushables.VetCollisionePushable[ItemIndex] & CP_COLLISION) {
		Altezza = pItem->OcbCode & 0x1f;
		Altezza = Altezza << 8;
		AlterFloorHeight(pItem, Altezza);
		GlobTomb4.BasePushables.VetCollisionePushable[ItemIndex] &= ~CP_COLLISION;
	}



}
// oggetto contiene il numero di slot del tipo di oggetto
// raccolto
// se e' una delle scatole di munizioni da gestire effettua
// l'aggiornameto e poi restituisce true
// in caso contrario restituisce false
bool AnalisiScatolaMunizioni(WORD Oggetto)
{
	StrBaseCustomize *pCust;

	short *VetMun;

	pCust= GlobTomb4.pBaseCustomize;

	VetMun = GlobTomb4.pAdr->pVetAmmos;



	switch (Oggetto) {
	case 354:
		// SHOTGUN_AMMO1_ITEM
		if (VetMun[MUN_SHOTGUN_NORMALS]  == -1) break;
		VetMun[MUN_SHOTGUN_NORMALS] += pCust->AmmoFucileNormale.Pickup;
		break;

	case 357:
		// CROSSBOW_AMMO1_ITEM
		if (VetMun[MUN_CROSSBOW_NORMALS]  == -1) break;
		VetMun[MUN_CROSSBOW_NORMALS] += pCust->AmmoBalestraNormali.Pickup;
		break;

	case 367:
		// SIXSHOOTER_AMMO_ITEM
		if (VetMun[MUN_REVOLVER]  == -1) break;
		VetMun[MUN_REVOLVER] += pCust->AmmoRevolver.Pickup;
		break;

	case 350:
		// PISTOLS_AMMO_ITEM
		if (VetMun[MUN_PISTOLS]  == -1) break;
		VetMun[MUN_PISTOLS] += pCust->AmmoPistols.Pickup;
		break;

	case 352:
		// UZI_AMMO_ITEM
		if (VetMun[MUN_UZI]  == -1) break;
		VetMun[MUN_UZI] += pCust->AmmoUZI.Pickup;
		break;
	default:
		return false;
	}
	return true;

}
