// usdata in tomb5, per visualizzare i suoni mostrati
char *TestoSFXSuonati(void)
{
	StrRecordSFXSuonato *pSfx;
	static char BufferSuoni[256];
	DWORD *pFrameNow = (DWORD *) 0xE4B1FC;
	int i,j;
	DWORD FrameNow;
	int TotOld;
	char *pChar;

	FrameNow = *pFrameNow;

	strcpy(BufferSuoni,"\nSFX Playing: ");
	TotOld = GlobTomb4.BaseSfxPlayed.TotSuonati;
	pSfx = &GlobTomb4.BaseSfxPlayed.VetSuonati[0];
	BufferSuoni[0]=0;

	i=0;
	for (j=0;j<TotOld;j++) {
		if ((FrameNow - pSfx->FrameStart) < FRAME_SECONDO * 2) {
			// e' ancora vaido
			if (j != i) {
				// copiarlo
				GlobTomb4.BaseSfxPlayed.VetSuonati[i] =
					*pSfx;

			}
			pChar = FormattaSuono(pSfx->Suono);
			strcat(BufferSuoni, pChar);
			i++;
		}
		pSfx++;
	}
	GlobTomb4.BaseSfxPlayed.TotSuonati = i;

	return BufferSuoni;

}
// chiamata in game da tomb5
void EseguiInGameTomb5(void)
{

	StrRobaTomb5 *pTomb;
	StrItemTr4 *pLara;
	WORD NextAnim;
	int AnimNow;
	DWORD CountNow;


	if (*MyGlobPrivate.RobaTomb5.pLevelNow == 0) return;
	pTomb = &MyGlobPrivate.RobaTomb5;

	if (TastoVKPremuto(VK_F7)==true) GlobTomb4.pDiagnostica->TestPremutoF7 =true;
	if (TastoVKPremuto(VK_F8)==true) GlobTomb4.pDiagnostica->TestPremutoF7=false;


	if (GlobTomb4.pDiagnostica->TestPremutoF7) {
		SalvaStringaTr5(20,pTomb->CordY ,0, "LOG");
		pTomb->CordY += pTomb->StepY;
	}


	pLara = pTomb->pLara;
	AnimNow = pTomb->pLara->AnimationNow;
	NextAnim = pTomb->pVetAnimations[AnimNow].NextAnimation;
	CountNow = GetTickCount() - pTomb->StartTime;

	sprintf(BufferLog,"Anim=%d (Next=%d)\nStateId=%d (Next=%d)\nRoom=%d  Level=%d\nSFX: %s",
		AnimNow, NextAnim, 
		pLara->StateIdCurrent, pLara->StateIdNext, 
		pLara->Room, *pTomb->pLevelNow,
		TestoSFXSuonati());


	SalvaStringaTr5(20,pTomb->CordY , 0, BufferLog);

	pTomb->CordY += pTomb->StepY * 3;

	if (GlobTomb4.pDiagnostica->TestPremutoF7 && 
		GlobTomb4.pDiagnostica->TotRecord == 0) {

		sprintf(BufferLog,"Anim=%d  (Next=%d) StateId=%d (Next=%d) HSpeed=%d  VSpeed=%d  Room=%d",
			AnimNow, NextAnim, pLara->StateIdCurrent, pLara->StateIdNext, pLara->SpeedH, pLara->SpeedV, pLara->Room);
		InviaLog(BufferLog);
	}


	DiagnosticaWatch(true);


}
