// chiamata da patch per movecamera
// se la stanza e' palude modifica Camera_SourceY in modo che
// la camera sorgente NON sia inserita dentro la palude
void AggiustaCameraSource(short NRoom)
{

	StrRoomTr4 *pRoom;
	int NewY;

	pRoom = &GlobTomb4.pAdr->pVetRooms[NRoom];

	if (pRoom->FlagsRoom & 0x04) {
		// e' palude
		// ora trovare topyroom
		NewY = pRoom->OrigYTop - 0x100;
		if (GlobTomb4.pAdr->Camera.pCameraSrc->CordY > NewY) 
					GlobTomb4.pAdr->Camera.pCameraSrc->CordY = NewY;
	}

}
// controlla se 256 cord y sotto target camera attuale
// c'e' un stanza palude
// se c'e' modifica cordytargetcamera in modo da mantenerla sopra
// nota: se NRoom e' uguale a -1 allora usa room di struttura pCam
// se invece e' diversa da -1 usa quel valore come impostazione iniziale
// se c'e' l'aggiornamento restituisce true
bool AggiustaCameraCords(GAME_VECTOR *pCam, short IndiceRoom)
{
	void *pFloor;
	short Room;
	int  CordY;

	if (IndiceRoom == -1) {
		Room = pCam->Room;
	}else {
		Room = IndiceRoom;
	}

	CordY = pCam->CordY  + 0x100;
	pFloor = GetFloor(pCam->CordX , CordY, pCam->CordZ , &Room);

	if (GlobTomb4.pAdr->pVetRooms[Room].FlagsRoom & 0x04) {
		// camera e' palude
		CordY = GlobTomb4.pAdr->pVetRooms[Room].OrigYTop - 0x100;
		pCam->CordY = CordY;
		return true;
	}
	return false;
}

// restituisce true se i piedi di lara sono in palude
bool IsLaraPiediInPalude(void)
{
	StrMovePosition  TriRec;
	void *pFloor;
	short Room;
	int BaseLaraY;

	TriRec.RelX=0;
	TriRec.RelY = 0;
	TriRec.RelZ=0;
	GetJointAbsPosition(GlobTomb4.pAdr->pLara, 
				&TriRec, JOINT_LEFT_ANCKLE);
	BaseLaraY = TriRec.RelY;	
	
	Room = GlobTomb4.pAdr->pLara->Room;
	pFloor = GetFloor(GlobTomb4.pAdr->pLara->CordX, BaseLaraY, 
		GlobTomb4.pAdr->pLara->CordZ, &Room);

	if (GlobTomb4.pAdr->pVetRooms[Room].FlagsRoom & 0x4) return true;
	return false;

}
// chiamata dopo aver chiamato e inizializzato livello 
// rimuove il flag acqua dalle stanza che hanno flag palude

void RimuoviAcquaDaPalude(void)
{
	int i;

	StrRoomTr4 *pRoom;

	for (i=0;i<*GlobTomb4.pAdr->pTotRooms;i++) {
		pRoom = &GlobTomb4.pAdr->pVetRooms[i];

		if (pRoom->FlagsRoom & 0x4) pRoom->FlagsRoom &= ~0x1;
	}

}
// se diagnotica e' attiva,  memorizza il suono mancante
