// chiamato all'inizio di ogni riga di testo stampato
// bisogna usare i valori globali salvati in RobaScrolling
// e aggiornarne i valori
// se siamo arrivati oltre a zona schermo impostare TestFinePrint = true
void AnalisiCapoRiga(short CordY, char *pCharNow)
{
	int Offset;

	Offset = (int) (pCharNow - RobaScrolling.pAdrStringa);
	if (RobaScrolling.RigaInizio.TextOffset == -1) {
		// non ho ancora impostato riga iniziale
		// se cordy attuale e' >= 0 e caporigaold
		// e' impostato usare quei valori come prima riga
		if (CordY >= 0 && RobaScrolling.CapoRigaOld.TextOffset >=0) {
			// ok, usare caporigaold come RigaInizio
			RobaScrolling.RigaInizio = RobaScrolling.CapoRigaOld;


		}
	}

	// ora copiare il riga now attuale come riga old
	RobaScrolling.CapoRigaOld.OrgY = CordY;
	RobaScrolling.CapoRigaOld.TextOffset = Offset;

	if (CordY >= (*GlobTomb4.pAdr->pSizeScreenY + RobaScrolling.AltezzaRiga*2 )) {

		RobaScrolling.TestFinePrint=true;
	}

	RobaScrolling.LastCordY = CordY;


}
// chiamata PRIMA di stampare un carattere.
// pStringa punta a carattere da stampare e OrgX e' la posizione
// dove si stampera'

void AnalisiPosXCar(char *pStringa, short OrgX)
{


	DWORD Offset;
	DWORD i;


	if (OrgX < 0) {
		i =0;
	}



	if (RobaScrolling.ContaRighe == 0) {
		RobaScrolling.LastCordX = OrgX;

	

		if (OrgX <= RobaScrolling.LarghezzaCar) {
			// salvare
			Offset = (DWORD) (pStringa - RobaScrolling.pAdrStringa);
			RobaScrolling.PosizioneInizio.OffsetH = (short) Offset;
			RobaScrolling.PosizioneInizio.OrgX = OrgX;
		}
	}

	// ora fare analisi per vedere se siamo gia' oltre lo schermo x
	// se esi, andare fino in fondo a riga attuale
	RobaScrolling.ptr_NewStringa = pStringa;

	if (OrgX >= *GlobTomb4.pAdr->pSizeScreenX) {
		// saltare riga
		for (i=0;i<strlen(pStringa);i++) {
			if (pStringa[i] == 0x0a || pStringa[i] == 0x0) {
				RobaScrolling.ptr_NewStringa  = &pStringa[i];
				break;
			}
		}
	}

}
// converte (se necessario) stringa originale pStringa
// nel formato di vecchi codici tomb
// questo accade se NON e' attivo nuovo font
// e indirizzo di stringa e' diverso da quello interno BufferConvStringa
BYTE *ConvertiTestoAnsiTomb(BYTE *pStringa)
{
	int i;
	BYTE Codice;

	if (GlobTomb4.TestFontNew) return pStringa;
	
	// si usa vecchio tomb
	// in teoria ancrebbe convertito a meno che l'indirizzo
	// non sia incluso in zona di BufferConvStringa[65536]
	// perche 'in quel caso vuol dire che e' gia' stato convertito

	if (pStringa >= BufferConvStringa &&
		pStringa < &BufferConvStringa[65536]) return pStringa;

	// attenzione, se siamo in modalita' vecchi livelli 
	// (niente headr ng) nello script, allora non c'e' bisogno
	// di rifare la conversione perche' in realtr'a il testo sara'
	// gia' di tipo vecchio

	if (MyGlobPrivate.TestNG_NoScript==true) return pStringa;

	// ok, convertire tutti i caratteri
	i =0;

	while (pStringa[i]) {
		Codice = VetAscii2Tomb[pStringa[i]];
		BufferConvStringa[i++] = Codice;
	}
	BufferConvStringa[i] =0;

	return BufferConvStringa;	
		
}
