// controlla se c'e' bisogno di attivare softfull screen
// in caso affermativo modificare indice video in modo
// che corrisponda a quello della risoluzione di schermo
void AnalisiIndiceVideo(void)
{
	DWORD SizeX, SizeY;
	int Indice;
	int *pSetting_VMode = (int*) 0x7538A0;

	if (GlobTomb4.TestSoftFullScreen == false) return;



	// ok, ora fare tutti i calcoli
	SizeX= GlobTomb4.BaseWideScreen.SizeX;
	SizeY = GlobTomb4.BaseWideScreen.SizeY;

	// ora usare la funzione che mi da l'indice
	Indice = TrovaIndiceVideo(SizeX,SizeY);

	if (Indice == -1) {
		sprintf(BufferLog,"ERROR: cann't find a cooperative video mode with resolution: %d x %d",
			SizeX, SizeY);
		InviaLog(BufferLog);
		GlobTomb4.TestSoftFullScreen=false;
		return;
	}
	sprintf(BufferLog,"Changed video mode to cooperative level. VideoIndex=%d SizeX=%d  SizeY=%d",
		Indice, SizeX, SizeY);
	InviaLog(BufferLog);

	// nota: i valorida modiicare sono gia' stati salvati in precedenza
	*pSetting_VMode= Indice;



}
// controlla se il savegame ha una zona moveable grande o piccola
// salva il valore in TestBigZonaMoveable
void ControllaSizeSavegame(char NomeSave[])
{

	StrExtractNG TempHeader;


	if (VerifyNGHeader(NomeSave, &TempHeader)==false) {
		// niente headr, allora dimensione corta
		TestBigZonaMoveable =false;
		return;
	}
	// header e' presente, vedere da dove parte

	if (TempHeader.StartOffset == 0x3E52) {
		TestBigZonaMoveable=false;
	}else {
		// e' in posizione diversa: allora e' grande
		TestBigZonaMoveable=true;
	}


}
// verifica se l'item la cui struttura inizia in BaseItem
// ha un indice di quelli compresi tra quelli frozen
bool IsItemFrozen(DWORD BaseItem)
{
	DWORD Temp;
	int i;

	Temp = (DWORD ) GlobTomb4.pAdr->pVetItems;

	BaseItem -= Temp;
	BaseItem /= sizeof(StrItemTr4);
	
	for (i=0;i<GlobTomb4.BaseFreeze.TotFreeze;i++) {
		if (BaseItem == GlobTomb4.BaseFreeze.VetFreeze[i].ItemIndex) return true;
	}

	return false;

}
