// chiamata subito dopo aver caricato script.dat
// effettua un controllo sui livelli presenti in script.dat
void Controllo2Missing(void)
{
	char **p2BasePathLivelli = (char**) 0x7FD16C; // Ptr_BaseNomiLivelliDat
	char *pBasePathLivelli;
	int i;
	char *pChar;
	int n;
	char NomeFile[256];
	BYTE *pVetNomiLivelli = (BYTE *) 0x7FD1A0; // VetIndiceStringaNomeLivello
	int j;
	char MexMissing[] = "MISSING";
	char *pNome;
	int Indice;

	if (GlobTomb4.BaseMissing.TestScriptPresenti==false) return;
	
	pBasePathLivelli = *p2BasePathLivelli;

	i=0;
	n=0;
	do {
		pChar = &pBasePathLivelli[i];
		if (pChar[0] == 0) break;
		sprintf(NomeFile, "%s.TR4", pChar);
		if (EsisteFile(NomeFile)==false) {
			if (n == 0) {
				// manca title
				sprintf(BufferLog,"CRITICAL ERROR: missing title level \"%s\"\r\n",
					NomeFile);
				strcat(GlobTomb4.BaseMissing.MexMissing, BufferLog);

				GlobTomb4.BaseMissing.TestErrori=true;
			}else {
				// manca un livello generico
				sprintf(BufferLog,"WARNING: missing \"%s\" level file\r\n",
					NomeFile);
				strcat(GlobTomb4.BaseMissing.MexMissing, BufferLog);
				GlobTomb4.BaseMissing.TestAvvisi=true;
				// ok, ora provare ad eliminare il nome del ile
				// accedendo alla stringa

				Indice = pVetNomiLivelli[n];
				if (Indice) {
					pNome = GetString(Indice);
					for (j=0;j<(int) strlen(pNome);j++) {
						if (j >= (int) strlen(MexMissing)) {
							pNome[j]=0;
							break;
						}
						pNome[j] = MexMissing[j];
					}
					
				}

			}
	
		}
		i += strlen(pChar)+1;
		n++;

	}while(n);


}
// aggiunge luce fanale per jeep.

void FanaleJeep(StrItemTr4 *pJeep)
{
	StrItemTr4 *pLara;
	static DWORD *pTestTorciaAccesa = (DWORD *)  0x536DE0; // TestTorciaAccesa


	pLara =GlobTomb4.pAdr->pLara;
	// provare a modiicare teporaneaente gli orientamti
	// per correggere gli errori di piazzanrto mesh
	if (pLara->StateIdCurrent != 9 && pLara->StateIdCurrent != 10) {
		pJeep->OrientationT += 0x4000;
		pJeep->OrientationH += 0x4000;
		AddEffectLight(pJeep , 0, 0, -350, 400, 255, 20, 0, 0, ADD_LIGHT_SPOT);
		AddEffectLight(pJeep, 0, 0, -300, 762, 16, 0, 0, 4, ADD_LIGHT_FLAT);

		pJeep->OrientationH -= 0x4000;
		pJeep->OrientationT -= 0x4000;
		pJeep->MeshVisibilityMask |= (2 << 18);

	}else {
		*pTestTorciaAccesa=0;
		pJeep->MeshVisibilityMask &= ~(2 << 18);
	}
}
void TrovaDartCustomize(int IndiceDartEmitter) 
{
	// se questo dart emitter ha un valore ocb diverso da zero
	// imposta struttura globale con i dati di questa customizzazione
	// in valore globale StrDartCustomize *pDartCustNow;
	// mentre se ocb = 0 imposta NULL in pDartCustNow che vuol
	// dire che non c'e' alcuna customizzzione

	WORD OcbIndex;
	int i;
	StrDartCustomize *pNow;

	pDartCustNow = NULL;
	OcbIndex = GlobTomb4.pAdr->pVetItems[IndiceDartEmitter].OcbCode;
	if (OcbIndex == 0) return;

	// trovare il record di custoizzazione
	pNow = &GlobTomb4.pBaseCustomize->BaseDartCustomization.VetCust[0];

	for (i=0;i<GlobTomb4.pBaseCustomize->BaseDartCustomization.TotCust;i++) {
		if (pNow->IdCustomize == OcbIndex) {
			pDartCustNow =pNow;
			return;
		}
		pNow++;
	}


}
