// aggiunge eventuali effetti al flare
void AggiungiFlareCust(StrMovePosition *pPos, int TempoPassato)
{

	int CordX, CordY, CordZ;
	int IncY;
	StrCustFlare *pFlare;
	DWORD TestFumo;
	DWORD Colore;
	int Numero;
	int Valore;


	pFlare = &GlobTomb4.pBaseCustomize->BaseFlare;


	//TriggerFlareSparks
	if (pFlare->Flags & FFL_ADD_SPARKS) {

		// creare dati per spark
		CordX = pPos->RelX;
		CordY = pPos->RelY;
		CordZ = pPos->RelZ;

		// se e' random alterare leggermente sia coordinate che colori


		if (pFlare->Flags & FFL_ADD_SMOKE_TO_SPARKS) {
			TestFumo=1;
		}else {
			TestFumo=0;
		}

		IncY = -256;
		// ora fare una bassa intensita' all'inzio e all fine del flare
		if (TempoPassato < 30 || TempoPassato > (short) pFlare->Valore876) {
			IncY = -100;

		}
		
		TriggerFlareSparks(CordX, CordY, CordZ, 
							0, IncY, 0, TestFumo, 1);
		// visto che le spark reguali sono un po' piccine raddoppiarle
		// per renderle piu' appetibili
		TriggerFlareSparks(CordX, CordY- 20, CordZ, 
							0, IncY / 2, 0, 0, 1);
		
	}

	if (pFlare->Flags & FFL_ADD_FIRE) {
		AddFire(pPos->RelX , pPos->RelY-50 , pPos->RelZ , 
					0, GlobTomb4.pAdr->pLara->Room ,0);

		SoundEffect(0x96, NULL, 0);
	}

	if (pFlare->Flags & FFL_ADD_GLOW_LIGHT) {
		Colore= pFlare->Blu;
		Colore |= (pFlare->Verde << 8);
		Colore |= (pFlare->Rosso << 16);
		if (pFlare->Flags & FFL_FLAT_LIGHT) {
			Numero = 80;
		}else {
			Numero = (GetRandomControl() & 0x1f) + 64;
		}
		// far diminuire intensita nell'ultimo secondo
		Valore= pFlare->Durata - TempoPassato;
		Valore = 30 - Valore;
		if (Valore >= 0) {
			
			Valore *=3;
			Numero -= Valore;

			if (Numero < 0) Numero=0;
		}
		Colore |= (Numero << 24);
		TriggerLightningGlow(pPos->RelX - 30, pPos->RelY, pPos->RelZ, Colore);

	}

		
}
// nota: in tipofish (0,1,2 oppure 3)
void DisegnaPesce(DWORD CordX, int CordY, DWORD CordZ, 
					 int TipoFish, short HOrient, short VOrient, short ROrient)
{
	StrMeshTr4 *pMesh;
	int IndiceMesh;


	IndiceMesh = GlobTomb4.pAdr->pVetSlot[491].IndexFirstMesh;


	pMesh = GlobTomb4.pAdr->VetMeshPointer[IndiceMesh+(TipoFish << 1)];

	phd_PushMatrix();
	phd_TranslateAbs(CordX, CordY, CordZ);

	phd_RotYXZ(HOrient, VOrient, ROrient);
	phd_PutPolygons_train(pMesh, 0);

	*GlobTomb4.pAdr->pZonaRecord30 -= 0x30;

}

void AttaccaMesh(StrItemTr4 *pItem, StrMovePosition *pMove, 
				 int JointMesh, int TotMesh)
{
	StrMeshTr4 *pMesh;
	GetJointAbsPosition(pItem, pMove, JointMesh);

	pMesh = GlobTomb4.pAdr->VetMeshPointer[TotMesh];

	phd_PushMatrix();
	phd_TranslateAbs(pMove->RelX , pMove->RelY , pMove->RelZ );

	phd_RotYXZ(pItem->OrientationH , 
		pItem->OrientationV, 
		pItem->OrientationT);

	phd_PutPolygons_train(pMesh, 0);

	*GlobTomb4.pAdr->pZonaRecord30 -= 0x30;
}

void DisegnaMioPesce(StrFish *pFish)
{
	short OrientR;
	WORD TipoFish;
	DWORD Offset;


	TipoFish = (pFish->FlagFish  & FISH_MASK_MESH) >> 5;


	if (pFish->TipoFase == FISH_DEATH_ON_GROUND) {

		Offset = (DWORD) pFish;
		if (Offset & 0x04) {
			OrientR = 0x4000;
		}else {
			OrientR = -0x4000;
		}
	}else {
		OrientR = 0;
	}

	if (pFish->TipoFase == FISH_DYING_ON_GROUND) {
		OrientR = (GetRandomControl() & 0x7ff) - 0x3ff;
	}

	DisegnaPesce(pFish->CordX, pFish->CordY, pFish->CordZ, 
		TipoFish, pFish->OrientH, pFish->OrientV, OrientR);

}

void ClearFish(void)
{
	StrFish *pFish;
	int i;


	pFish = (StrFish *) 0x80EBE0;
	
	for (i=0;i<128;i++) {
		if (pFish->TipoUsato == 2) pFish->TipoUsato =0;
		pFish++;
	}

}
// calcola un box di collisione ristretto per lara che sara' usato
// da fish
void CalcolaBoxCollisioniFish(void)
{
	StrAbsBoxCollision *pBox;
	StrBoxCollisione *pBound;
	DWORD LaraX;
	int LaraY;
	DWORD LaraZ;

	// eseguirlo solo se oggetto FISH_EMITTER e' presente
	if ((GlobTomb4.pAdr->pVetSlot[491].Flags & 1) == 0) return;

	pBound = GetBoundsAccurate(GlobTomb4.pAdr->pLara);
	
	LaraX= GlobTomb4.pAdr->pLara->CordX;
	LaraY= GlobTomb4.pAdr->pLara->CordY;
	LaraZ= GlobTomb4.pAdr->pLara->CordZ;

	if (*GlobTomb4.pAdr->pLaraLocationFlags == 2) {
		// lara sta galleggiando, spostare box piu' in basso
		LaraY += 250;
	}
	// correggere y di lara se sta galleggiando
	pBox = &GlobTomb4.GlobFish.BoxCollisionLara;

	pBox->MinX = LaraX + (pBound->MinX >> 1);
	pBox->MaxX = LaraX + (pBound->MaxX >> 1);

	pBox->MinY = LaraY + (pBound->MinY >> 1);
	pBox->MaxY = LaraY + (pBound->MaxY >> 1);

	pBox->MinZ = LaraZ + (pBound->MinZ >> 1);
	pBox->MaxZ = LaraZ + (pBound->MaxZ >> 1);

	

}
// se versione e' maggiore o uguale a 1.2.2.0 
// verifica se slot e' incluso nel massimo shatter
// se invece versione e' inferiore considera SEMPRE slot
// come se fosse shatter (per compataibilita' con le versioni precenti)
bool IsShatter(WORD SlotStatico, StrVersionHeader *pVersione)
{
	if (ConfrontaVersioni(pVersione, "1.2.2.0") < 0) return true;

	if (SlotStatico > GlobTomb4.pBaseCustomize->ShatterFine) return false;

	return true;


}

