// viene chiamata in getheiht o getceiling per vedere 
// se c'e' un rigger per oggetto bridge floor o twoblock platform ecc
// restituisce true/false
// nota viene chiamata sia per floor che per ceiling
// e sostituisce alle coordinate di lara quelle 
// globtomb4.dummyx globtomb4.dummy globtomb4.dummyz
// NOTA: nuova modifica: se e' condzione diversa da quella di frgamented triggers
// non eseguirla e restituire false (incluse tutte le condizioni di plugin)
// qualche dubbio vada bene
bool AnalisiCondDummy(WORD *pVetFloor)
{
	WORD Condizione;
	WORD Indice;
	WORD ExtraButtons;
	bool TestRestore;  // ripristina pulsanti trigger
	int ValEsito;
	bool TestSalta;
	int TipoBlocco;
	DWORD SalvaX, SalvaZ;
	int SalvaY;
	StrItemTr4 *pLara;
	DWORD OffsetCondition;
	WORD PluginId;
	DWORD OffsetNow;

	static DWORD *ptr_MemoriaFloor = (DWORD *) 0x533948;
	// dare per scontato che sia condizione visto che PARAMETER e' usato solo
	// per condizione
	TipoBlocco=0;

	Condizione = pVetFloor[0] & 0xff;

	// scoprire plugin di condizione
	OffsetCondition = (DWORD) pVetFloor;  // punta a pulsanti e timer
	OffsetNow = OffsetCondition - (*ptr_MemoriaFloor);

	PluginId= TrovaPluginIdTrigger(OffsetNow >> 1, true);
	// se appartiene ad un plgin uscire subito con false
	if (PluginId > 0) return false;


	Indice = pVetFloor[1] & 0x3ff;
	ExtraButtons = pVetFloor[0] >> 9;
	ExtraButtons &= 0x1f;

	if (IsValidConditionForDummy(Condizione, Indice, true)==false) {

		// e' altra roba: 
		return false;
	}

	TestRestore  =false;
	ValEsito=0;
	TestSalta=true;

	pLara = GlobTomb4.pAdr->pLara;

	SalvaX = pLara->CordX;
	SalvaY = pLara->CordY;
	SalvaZ = pLara->CordZ;

	GlobTomb4.pDiagnostica->TestSospendiBreakCond =true;
	pLara->CordX = GlobTomb4.DummyX;
	pLara->CordY = GlobTomb4.DummyY;
	pLara->CordZ = GlobTomb4.DummyZ;
	// qui do pe rscontato che sia condizione di trng (pluginid=0) ma come faccio a saperlo per certo?
	ValEsito=EseguiCondizione(0, Condizione, Indice, ExtraButtons, 
								&TestRestore,  &TestSalta, &TipoBlocco, SCANF_DIRECT_CALL);


	// ripristinare coord lara
	pLara->CordX = SalvaX;
	pLara->CordY = SalvaY;
	pLara->CordZ = SalvaZ;
	
	GlobTomb4.pDiagnostica->TestSospendiBreakCond =false;

	if (ValEsito == 0) {
		GlobTomb4.TestDummyFalse=true;
		return false;
	}
	
	return true;


}
// lara e' stata colpita da fulmine flame3
// situazione diversa a seconda di ocb 
void ColpitaFlame3(StrItemTr4 *pFlame)
{
	StrItemTr4 *pLara;
	short Danno;
	int i;

	//
	// 888 = infiamma e uccide lara immediatamente
	// 889 = danneggia vitalita lara e se scende a zero la infiamma e uccide
	// 890 = nessun danno

	if (pFlame->OcbCode == 890) return;
	if (*GlobTomb4.pAdr->pFlagsLara & 0x08) return;

	pLara = GlobTomb4.pAdr->pLara;

	if (pFlame->OcbCode == 889) {
		// qui diversi danni a seconda di acqua
		// se lara sottacqua -1
		// se lara galleggia o gocce sul corpo - 5
		// altrimenti -10
		Danno = -10;
		if (*GlobTomb4.pAdr->pLaraLocationFlags == 1) {
			// sott'acqua
			Danno=-1;
		}else {
			if (*GlobTomb4.pAdr->pLaraLocationFlags == 2) {
				// lara galleggia
				Danno=-5;
			}
		}
		if (Danno == -10) {
			// vedere se ci sono gocce

			for (i=0;i<16;i++) {
				if (GlobTomb4.pAdr->pVetDrip[i]) {
					Danno=-7;
					break;
				}
			}			
		}
		if (pLara->Health >0) pLara->Health += Danno;
		pLara->FlagsMain |= 0x10;
		if (pLara->Health > 0) return;
	}
	// infiammare lara e ucciderla
	LaraBurn();
	pLara->Health=0;
	pLara->FlagsMain |= 0x10;

}
// verificare se in punto pPoint c'e' una collisione tra pVeicolo
// e qualche altro moveable o static
bool AnalisiCollVeicoli(int CordX, int CordY, int CordZ)
{

	StrItemTr4 *pItem;
	int i;
	StrVetItemCollision  *pBase;
	int Indice;
	int Room;
	int j;
	StrSlotVehicleCollide *pCust;
	StrItemTr4 *pVeicolo;
	WORD Slot;
	bool TestIgnora;
	StrRoomTr4 *pRoom;
	StrPos3d PosStatic;
	StrMeshInfo *pStatic;
	StrBoxCollisione *pCollStatic;

	pBase = &GlobTomb4.BaseCollItem;
	pVeicolo = pBase->pVeicolo;

	CheckPoint.OrgX = CordX;
	CheckPoint.OrgY = CordY;
	CheckPoint.OrgZ = CordZ;

	for (i=0;i<pBase->TotMoveables;i++){
		Indice= pBase->VetMoveables[i] & FCV_MASK_INDEX;
		pItem = &GlobTomb4.pAdr->pVetItems[Indice];
		// se e' bike verificare se e'uno slot per cui e' previsto hurt o pushaway
		// nel qual caso NON analizzare
		Slot = pItem->SlotID;
		j = *GlobTomb4.pAdr->pVehicleIndex;
		TestIgnora=false;
		if (GlobTomb4.pAdr->pVetItems[j].SlotID == 31) {
			// e' la moto
			pCust = &GlobTomb4.pBaseCustomize->BaseSlotCollideVehicles;
			for (j=0;j<pCust->TotSlotCollide;j++) {
				if ((pCust->VetSlotCollide[j] & HIT_MASK_SLOT) == Slot)  {
					if (pCust->VetSlotCollide[j] & (HIT_HURT | HIT_PUSH_AWAY)) {
						TestIgnora=true;
						
					}
					break;
				}
			}
		}
		if (TestIgnora==false) {

			if (CollideItemPoint(pItem, &CheckPoint, 64)==true) {
				// trovata collisione (dati in OutCollisioneBox)
				pBase->NewFloorY = pBase->OutCollisioneBox.MinY;
				pBase->VetMoveables[i] |= FCV_COLLISIONE;
				return true;

			}
		}
		
	}

	// ora lo stesso per gli static
	for (i=0;i<pBase->TotStatics;i++) {
		Indice = pBase->VetStatics[i].IndiceStatic & FCV_MASK_INDEX;
		Room = pBase->VetStatics[i].IndiceRoom;

		pRoom = &GlobTomb4.pAdr->pVetRooms[Room];
		pStatic = &pRoom->Ptr_StaticMesh[Indice];

		pCollStatic = &GlobTomb4.pAdr->pVetEditObjects[pStatic->SlotId].CollisionBox;
		PosStatic.Posizione.OrgX  = pStatic->x;
		PosStatic.Posizione.OrgY = pStatic->y;
		PosStatic.Posizione.OrgZ = pStatic->z;

		PosStatic.OrientH = pStatic->Orient;

		
		if (CollideStaticPoint(pCollStatic, &PosStatic, 64)==true) {
			pBase->NewFloorY = pBase->OutCollisioneBox.MinY;
			pBase->VetStatics[i].IndiceStatic |= FCV_COLLISIONE;
			return true;
		}

	}

	return false;
}

