// chiamata quando bike colpisco rollingball ed era impostato
// il flag HIT_PUSH_AWAY
// orientdir e' la direzione Bike -> rolling
// mentre speed era la velocita' della moto
bool GestioneBikeVsRollingBall(StrCustomItem *pColpito, StrItemTr4 *pVeicolo, 
							   WORD Speed, short *pOrientDir) 
{
	StrItemTr4 *pRoll;
	short DifOrient;
	StrItemTr4 *pLara;
	int Differenza;
	int IncX, IncZ;
	WORD OrientAlign;

	pRoll = &GlobTomb4.pAdr->pVetItems[pColpito->ItemIndex];

	// se rolling era gia' attivo, non fare altro
	// tranne perdita vita lara nel caso ci sia una collisione in direzioni
	// diverse

	if ((pRoll->Objectbuttons & 0x3e00) == 0x3e00) {

		// era gia' attivo
		// vedere se c''e direzione di impatto
		DifOrient = *pOrientDir - pRoll->OrientationH;

		if (abs(DifOrient) > 0x4000 &&
			(pRoll->Reserved_34 !=0 || pRoll->Reserved_36 != 0)) {
			// e' il rollingball che e' piombato addosso a lara
			pLara= GlobTomb4.pAdr->pLara;
			pLara->Health -= pRoll->SpeedH;
			pLara->FlagsMain |= 0x10;
			
		}

		return true;
	}
	// attivare rollingball
	pRoll->Objectbuttons |= 0x3e00;
	pRoll->ObjectTimer=0;
	pRoll->ContactFlags=0;
	AddActiveItem(pColpito->ItemIndex);
	pRoll->FlagsMain |= 2;

	// calcolare nuovo orientamento in mod che sia perpendicolare a muri
	OrientAlign = GetAlignedOrient( *pOrientDir,true, &Differenza);
	// ora calcolare i due incremneti
	IncX=0;
	IncZ=0;

	switch (OrientAlign) {
		case 0:
			// verso est
			IncZ = Speed;

			break;
		case 0x4000:
			// verso sud
			IncX = Speed;

			break;
		case 0x8000:
			// verso ovest
			IncZ = -Speed;

			break;
		case 0xC000:
			// verso nord
			IncX = -Speed;

			break;
	}
	pRoll->Reserved_34 = IncX;
	pRoll->Reserved_36 = IncZ;

	*pOrientDir = OrientAlign;
	return true;

}
// viene chiamata PRIMA di AnimateBike
// ricorda: coordinate e state id in pLara
// mentre velocita e record AI in pVeicolo
// se modifico dati pLara poi verranno agfgiornati 
// anche in pVeicolo (coordinate e orientamenti)
void CollBikeFinale(int *pTipoImpatto, bool TestMorta)
{
	int i,j;
	StrCustomItem Custom;
	StrVetItemCollision *pBase;
	bool TestIndietro;
	StrSlotVehicleCollide *pCustSlot;
	StrBoxCollisione *pColl;
	bool TestSpinta;
	bool TestNemico;
	WORD FlagImpatto;
	float Fattore;
	StrProgressiveAction *pAzione;	
	short OrientDir, OrientDif;
	StrItemTr4 *pItem;
	short NewOrient;
	int NuovoImpatto;
	int NuovaSpeed;
	int Indice;
	int BassoY, AltoY;
	StrCustomItem *pColpito;
	StrMeshInfo *pStatic;
	StrBoxCollisione *pCollStatic;
	StrRoomTr4 *pRoom;
	int Room;
	int *pInt;
	short *pShort;
	int IncX, IncZ;
	int DifY;
	StrItemTr4 *pLara;
	DWORD DifX, DifZ;
	WORD SlotNow;
	bool TestNoDistanza;

	pColpito=NULL;
	pBase = &GlobTomb4.BaseCollItem;
	pLara = GlobTomb4.pAdr->pLara;


	if (TestMorta) return;

	
	// cercare collisioni
	for (i=0;i<pBase->TotMoveables;i++) {

		// controllare con questo
		Indice = pBase->VetMoveables[i] & FCV_MASK_INDEX;
		pItem = &GlobTomb4.pAdr->pVetItems[Indice];

		pColl = GetBestFrame(pItem);
		Custom.CordX = pItem->CordX;
		Custom.CordY = pItem->CordY;
		Custom.CordZ = pItem->CordZ;
		Custom.MaxY = pColl->MaxY;
		Custom.MinY = pColl->MinY;
		Custom.hOrient = pItem->OrientationH;
		Custom.pBoxRel = pColl;
		Custom.ItemIndex = Indice;
		Custom.Slot= pItem->SlotID;
		


		if (CollideItemConCustom(pBase->pVeicolo, &Custom, 0) == true) {
			pColpito = &Custom;
			break;
		}


		
	}
	// se non e' stata trovato con moveable, provfare con static
	if (pColpito==NULL) {
		for (i=0;i<pBase->TotStatics;i++) {

			Indice = pBase->VetStatics[i].IndiceStatic & FCV_MASK_INDEX;
			Room = pBase->VetStatics[i].IndiceRoom;

			pRoom = &GlobTomb4.pAdr->pVetRooms[Room];
			pStatic = &pRoom->Ptr_StaticMesh[Indice];

			pCollStatic = &GlobTomb4.pAdr->pVetEditObjects[
							pStatic->SlotId].CollisionBox;


			Custom.CordX = pStatic->x;
			Custom.CordY = pStatic->y;
			Custom.CordZ = pStatic->z;
			Custom.MaxY = pCollStatic->MaxY;
			Custom.MinY = pCollStatic->MinY;
			Custom.hOrient = pStatic->Orient;
			Custom.pBoxRel = pCollStatic;
			Custom.ItemIndex=-1;
			Custom.Slot = -1;

			if (CollideItemConCustom(pBase->pVeicolo, &Custom, 0) == true) {

				pColpito = &Custom;
				break;
			}
			
		}
		
	}

	if (pColpito==NULL) return;
	
	

	// trovata una collisione
	// modificare i dati di veicolo in modo da avere rimbalzo
	// o variazione di rotazione
	pInt = (int *) pBase->pVeicolo->pZonaSavegame;
	pShort = (short *) pInt;
	NuovoImpatto=13;
	if (*pTipoImpatto == 0) {
		
		NuovaSpeed=pBase->pVeicolo->SpeedH;

	}else {
		NuovaSpeed= pBase->OldSpeed - (pBase->OldSpeed >> 2);
	}
	
	if (NuovaSpeed < 0) {
		TestIndietro=true;
	}else {
		TestIndietro=false;
	}




	
	//if (pBase->OldSpeed < 10) pBase->OldSpeed=10;
	//if (NuovaSpeed<0) NuovaSpeed=0;

	// impostare ai8
	pInt[2] = (NuovaSpeed << 8) | 0x80;

	// vedere se è una creatura
	// oppure se è uno degli slot con effetti speciali
	TestNemico=false;
	FlagImpatto=0;
	pCustSlot=&GlobTomb4.pBaseCustomize->BaseSlotCollideVehicles;

	if (pColpito->Slot != -1) {
		pItem = &GlobTomb4.pAdr->pVetItems[pColpito->ItemIndex];	
		if (pItem->FlagsMain & 0x02) TestNemico=true;

		// vedere se slot è uno di quelli usati in cust_bike_vs_enemy
		
		SlotNow=pItem->SlotID;
		for (i=0;i<pCustSlot->TotSlotCollide;i++)  {
			if ((pCustSlot->VetSlotCollide[i] & HIT_MASK_SLOT)==SlotNow)  {
				FlagImpatto = pCustSlot->VetSlotCollide[i] & HIT_MASK_FLAGS;
				break;
			}
		}


	}

	if (FlagImpatto & HIT_BIKE_EXPLODE) {
		// esplode moto
		pLara->MeshVisibilityMask=0;
		pLara->Health=0;
		pLara->Objectbuttons |= 0x100;
		BikeExplode(pBase->pVeicolo);
		
	}

	if ((FlagImpatto & HIT_PUSH_AWAY) ==0) {
		
		if (FlagImpatto & HIT_EXPLODE) {
			// fare esplodere moveable
			if (pBase->OldSpeed > 110) {
				EsecuzioneActionTrigger(0, 0x152, pColpito->ItemIndex, SCANF_DIRECT_CALL);
			
			}

		}
	}

	if (FlagImpatto & HIT_HURT) {
		i = pBase->OldSpeed >> 3;
		pItem->Health -= i;
	}

	if ((FlagImpatto & (HIT_BIKE_EXPLODE | HIT_EXPLODE)) && 
		 (FlagImpatto & HIT_PUSH_AWAY)==0) return;

	if (FlagImpatto & HIT_KILL) {
		pItem->Health=0;
	}

	// vedere se e' oggetto piccolo in basso (che provochera'salto)
	// o in alto che potrerbbe provocare morte di lara
	AltoY = pBase->OutCollisioneBox.MinY;
	BassoY = pBase->OutCollisioneBox.MaxY;

	DifY = pBase->pVeicolo->CordY - AltoY;
	if ((FlagImpatto & HIT_PUSH_AWAY) == 0) {

		if (NuovaSpeed >= 0x2a && DifY < 300 && DifY >= 60) {

			// fare salto
			// prima verificare che procedura di salto non fosse gia' stata
			// iniziata
			if (pBase->pVeicolo->StateIdCurrent  == 8){
				// era gia' iniziata
				return;
			}
			pBase->pVeicolo->OrientationV  += 0x300;
			pBase->pVeicolo->SpeedV -= 10;
			EseguiAnimNemico(pBase->pVeicolo, 22, 8);
			return;
		}

		if (DifY < 60 && DifY > 10) {
			if (pBase->pVeicolo->StateIdCurrent != 11) {
				// solo un traballamento
				if (TestIndietro==false) {
					EseguiAnimNemico(pBase->pVeicolo, 11,11);
				}
			}
			return;

		}
		// qui probabilmernte dovrei uscire con dify < 300 se velocitaà è bassa
		if (DifY <= 10) return;
		
		if (DifY < 300 && NuovaSpeed < 0x2a) {
			if (pBase->pVeicolo->StateIdCurrent != 11) {
				// solo un traballamento a meno che non si stia procedendo
				// all'indietro
				if (TestIndietro==false) {
					EseguiAnimNemico(pBase->pVeicolo, 11,11);
				
				}

			}
			return;		
		}

		// ora analisi per oggetto che colpisce lara in testa
		DifY = pBase->pVeicolo->CordY-BassoY;
		


		if (DifY >= 360 && DifY < 576) {
			// vedere che origine x,z sia molto vicina
			DifX = abs(pColpito->CordX - pLara->CordX);
			DifZ = abs(pColpito->CordZ - pLara->CordZ);

			if (DifX > 512 || DifZ > 512) return;
			

			NuovaSpeed = pBase->OldSpeed;
			if (abs(pBase->pVeicolo->SpeedV) > NuovaSpeed) 
							NuovaSpeed=abs(pBase->pVeicolo->SpeedV);

			if (DifY < 400 && NuovaSpeed >= 110 && TestNemico== false) {
				// esplode modo
				pLara->MeshVisibilityMask=0;
				pLara->Health=0;
				pLara->Objectbuttons |= 0x100;
				BikeExplode(pBase->pVeicolo);
				return;
			}

			if (DifY > 560 || TestNemico==true) {
				// solo perdita vita
				pLara->Health-= (pBase->OldSpeed >> 3);
				pLara->FlagsMain |= 0x10;
				return;

			}


			// qui mettere codice per ammazzare lara con dolore
			pLara->Health=-1;

			EseguiAnimNemico(pBase->pVeicolo, 0, 7);

			i = *GlobTomb4.pIndiceFirstAnimBike;
			

			pLara->AnimationNow = i;
			pLara->StateIdCurrent = 0;
			pLara->FrameNow = GlobTomb4.pAdr->pVetAnimations[i].FrameStart;
			
			return;

			
		}
	}
			
		



	// ora dovrei calcolare variazione di orientamento (da mettere in pVeicolo
	// trovare la direzione di impatto tra veicolo e oggetto
	OrientDir = mGetAngle(pBase->pVeicolo->CordX, pBase->pVeicolo->CordZ, 
								pColpito->CordX , pColpito->CordZ);
	OrientDir += 0x4000;

	// ora calcolare differenza rispetto a direzione di veicolo
	OrientDif = pBase->pVeicolo->OrientationH - OrientDir;

	// se velocita' e' zero c'e' collisione controllare che oggetto
	// non si sia avvicinato troppo e nel caso tenerlo a distanza
	TestNoDistanza=false;

	if (pColpito->Slot == -1 || (FlagImpatto & HIT_WALL) != 0) TestNoDistanza=true;
	// se e' slot di door nemmeno
	if (pColpito->Slot >= 322 &&  pColpito->Slot <= 335) TestNoDistanza=true;


	if (pBase->OldSpeed ==0 && TestNoDistanza==false){
		
		// tenere solo lontano nemico
		i = DistanzaPrecisaXZ(pBase->pVeicolo->CordX, pBase->pVeicolo->CordZ,
								pColpito->CordX, pColpito->CordZ);

		if (i < 1024) {
			// controllare e attivare bit di collisione per baddy
			TestCollision(pItem, GlobTomb4.pAdr->pLara);
		}
		if (i < 512) {

			// fare in modo che disranza sia 300 e non di piu'
			CalcolaIncremento(pItem->OrientationH - 0x7fff, 
				&IncX, &IncZ,512);
			pItem->CordX += IncX;
			pItem->CordZ += IncZ;

			
			return;

		}
	}	



	if (OrientDif >= 0) {
		pShort[11] = +200;

	}
	if (OrientDif < 0) {
		pShort[11] = -200;
	}



	// analisi per impatto con nemici o slot speciali

	if (FlagImpatto & HIT_PUSH_AWAY) {
		// qui faro' un'azione di spinta
		// per ora muoverlo di colpo
		// se oggetto NON e' enemy attivrlo come oggetto mosso
		// in modo da salvare erirpistiare la sua posizione
		if (TestNemico==false) 	AggiungiItemMosso(pColpito->ItemIndex);


		NewOrient = OrientDir;
		if (abs(OrientDif) > 0x1000) NewOrient -= pShort[11];
	
		TestSpinta=true;
		// se e' rollingball lo attiva
		if (pColpito->Slot == 130) {
			// e' rollingball
			TestSpinta=GestioneBikeVsRollingBall(pColpito, pBase->pVeicolo, 
				pBase->OldSpeed, &NewOrient);
			
		
		}		
		if (TestSpinta) {

			pAzione= &GlobTomb4.VetProgressiveActions[0];

			for (i=0;i<GlobTomb4.TotProgressiveActions;i++) {
				if (pAzione->ActionType == AZ_PUSH_AWAY &&
					pAzione->ItemIndex == pColpito->ItemIndex) break;
				pAzione++;
			}

			if (i == GlobTomb4.TotProgressiveActions) {
				i = CreaNuovaAzioneProgressiva();
				pAzione= &GlobTomb4.VetProgressiveActions[i];
			}
			// calcolare dimensione di oggetto
			i = abs(pColpito->pBoxRel->MaxX - pColpito->pBoxRel->MinX) +
				abs(pColpito->pBoxRel->MaxZ - pColpito->pBoxRel->MinZ) +
				abs(pColpito->pBoxRel->MaxY - pColpito->pBoxRel->MinY);
			// calcolare la dimnesione media dei lati
			Fattore = ((float) i) / 3.0f;
			// per esempio se e' un cubo di un settore sarebbe 1024
			// e in questo caso lo si deve spostare di poco
			Fattore = Fattore  / 512.0f;

			// ok, eseguirlo adesso
			i = abs(pBase->OldSpeed);
			pAzione->ActionType = AZ_PUSH_AWAY;
			pAzione->ItemIndex = pColpito->ItemIndex;
			pAzione->Arg1 = NewOrient;
			pAzione->Arg2 = i+ (i >> 1);  // velocita orizzontale

			pAzione->VetArg[0] =pItem->CordY;
			pAzione->VetArgShort[2] = -(i  / 2); // vspeed
			pAzione->VetArgShort[3] = -1;
			pAzione->VetArgWord[4] = FlagImpatto;
			pAzione->VetArgShort[5] = 0; // max velocita' di caduta

			//nel caso lo colpisca di striscio limitare di molto
			// velocita
			if (abs(OrientDif) > 0x1200) {
				pAzione->Arg2 /=2;
				pAzione->VetArgShort[2] /= 2;
			}

			// riduzione velocita' orizzontale
			pAzione->VetArgShort[6] = Float2Int( 4.0f * Fattore);
			if (pAzione->VetArgShort[6] < 1) pAzione->VetArgShort[6]=1;

			// rifduzione velocita' verticale
			pAzione->VetArgShort[7] = Float2Int( 6.0f * Fattore);
			if (pAzione->VetArgShort[7] < 1) pAzione->VetArgShort[7]=1;

			// salvare valore di shadow
			pAzione->VetArgWord[8] = GlobTomb4.pAdr->pVetSlot[pItem->SlotID].FootStep;

			// calcolare animazione
		
		
			// impostare animazione speciale se possibile
			i=-1;

			switch (pItem->SlotID) {
			case 35:
				// skeleton
				if (pAzione->Arg2 > 100) {
					i = 17;
				}else {
					i= 35;
				}

				break;
			case 37:
				// guide
				i=57;

				break;
			case 39:
				// von croy
				if (pAzione->Arg2 > 100) {
					i = 22;
				}else {
					i= 51;
				}

				break;

			case 47:
				// mummy
				if (pAzione->Arg2 > 100) {
					i = 10;
				}else {
					i= 3;
				}

				break;
			case 49:
				// sphinx
				i=6;

				break;
			case 55:
				// scorpion
				i=7;

				break;
			case 61:
				// KNIGHTS_TEMPLAR
				i=6;

				break;
			case 65:
				// horse
				if (pAzione->Arg2 > 100) {
					i = 13;
				}else {
					i= 3;
				}

				break;
			case 67:
				// baboon_normal
				if (pAzione->Arg2 > 100) {
					i = 27;
				}else {
					i= 7;
				}

				break;
			case 75:
				// harpy
				if (pAzione->Arg2 > 100) {
					i = 17;
				}else {
					i= 12;
				}

				break;

			case 80:
				// dog
				i=2;


				break;

			case 102:
				// ahmet
				if (pAzione->Arg2 > 100) {
					i = 4;
				}else {
					i= 8;
				}

				break;
			}
			if (i !=-1) {
				// non eseguirla se e' gia' attiva
				j=pItem->SlotID;
				j = GlobTomb4.pAdr->pVetSlot[j].IndexFirstAnim;

				if ((i+j) != pItem->AnimationNow) {
					EseguiAnimNemico(pItem, i, -1);	

				}

			}
		}
		
	}
	// calcolare tipo impatto
	// 


	if (pBase->OldSpeed > 0x2a && pBase->pVeicolo->StateIdCurrent != 12 &&
		pBase->pVeicolo->StateIdCurrent != 15) {
		// impostare animazione di scossone
		EseguiAnimNemico(pBase->pVeicolo, 12, 12);
		if (pBase->OldSpeed > 60) {
			pLara->Health-= (pBase->OldSpeed >> 3);
			pLara->FlagsMain |= 0x10;
		}
	}




	if (*pTipoImpatto==0) {
		// non c'era impatto, creare ora dati mancanti
		// per evitare che moto si sia incastrata nell'oggetto
		// muoverlo in direzione opposta del doppio della vfelocita'

		CalcolaIncremento(OrientDir+0x7fff, &IncX, &IncZ, pBase->OldSpeed);

		pBase->pVeicolo->CordX += IncX;
		pBase->pVeicolo->CordZ += IncZ;


	}
	// se non c'era impatto rilevato ma in pratica c'e' adesso ridurre
	// velocita'
	if (*pTipoImpatto==0) {
		NuovaSpeed -= NuovaSpeed >> 1;
		pBase->pVeicolo->SpeedH = NuovaSpeed;
		// impostare ai8
		pInt[2] = (NuovaSpeed << 8) | 0x80;
	}
	*pTipoImpatto = NuovoImpatto;
	

}

bool ControllaCollEnemy(WORD SlotNow)
{
	StrSlotVehicleCollide *pBase;
	int i;
	WORD Flags;

	pBase = &GlobTomb4.pBaseCustomize->BaseSlotCollideVehicles;

	for (i=0;i<pBase->TotSlotCollide;i++) {
		if ((pBase->VetSlotCollide[i] & HIT_MASK_SLOT) == SlotNow) {
			Flags = pBase->VetSlotCollide[i] & HIT_MASK_FLAGS;
			if (Flags== 0 || Flags == HIT_KILL) break;
			return false;
		}
	}
	return true;


}
//  chiamata prima di DrawAnimating
// verificare se per questo item c'e' un'animazione da sostituire
void AnalisiDrawAnimating(StrItemTr4 *pItem)
{
	int i;
	short Slot;
	int AnimNow;
	int ItemIndex;
	bool TestEsito;
	int n;
	StrDatiDiagAnim *pDiag; 
	StrAnimObjScript *pAnimSlot;
	int j;


	if (GlobTomb4.BaseAnimObj.TotAnimObj==0) return;
	Slot = pItem->SlotID;

	ItemIndex = GetIndiceItem((DWORD) pItem);


	AnimNow = pItem->AnimationNow - GlobTomb4.pAdr->pVetSlot[Slot].IndexFirstAnim;
	
	pAnimSlot  = &GlobTomb4.BaseAnimObj.VetAnimObj[0];

	
	for (i=0;i<GlobTomb4.BaseAnimObj.TotAnimObj;i++) {
		if (pAnimSlot->Slot == Slot) {
			TestEsito=false;

			// eseguirla solo se ci sono tutte le condizioni

			TestEsito=EseguireAnimazioneScript(&pAnimSlot->Animation, pItem, false, ItemIndex);
			
			if (pAnimSlot->Animation.AnimIndex < 0) {
				// salvare esito
				n=GlobTomb4.BaseDiagnosiAnimSlot.TotAnim;

				pDiag= &GlobTomb4.BaseDiagnosiAnimSlot.VetDiag[0];
				for (j=0;j<n;j++) {
					if (pDiag->ItemIndex == ItemIndex) break;
					pDiag++;
				}

				
				if ( j < MAX_ANIM_DIAGNOSTIC) {

					pDiag = &GlobTomb4.BaseDiagnosiAnimSlot.VetDiag[j];

					pDiag->NumAnim = pAnimSlot->Animation.AnimIndex;
					pDiag->ReplaceAnim = pAnimSlot->ActionType;
					pDiag->TestEsito  = TestEsito;
					pDiag->ItemIndex = ItemIndex;
					pDiag->Slot = Slot;
					GlobTomb4.BaseDiagnosiAnimSlot.TotAnim++;
				}
			}

		}
			
		pAnimSlot++;
	}


}
// rilsciae eventali plugins presenti
void LiberaPlugins(void)
{
	DWORD i;
	StrMyDatabase *pDb;
	pDb = &MyGlobPrivate.DataBase;

	for (i=1;i<pDb->TotPlugins ;i++) {
		FreeLibrary(pDb->pVetPlugins[i].hDllPlugin);
	}

	

}
// chiamata dopo aver caricato script
void PreparaPushAway(void)
{
	// imposta i valori delle animazioni che hanno flag FAN_DISABLE_PUSH_AWAY
	StrDisablePushAway *pBase;
	BaseAnimScript *pAnim;
	int i;

	pBase = &GlobTomb4.BaseDisablePushAway;

	pBase->TotDisable =0;

	// se e' attivo il customize CUST_DISABLE_PUSH_AWAY_ANIMATION, non fare altri
	// calcoli perche' il push_away sara' sempre disabilitato

	if (GlobTomb4.pBaseCustomize->TestDisablePushAway == true) return;

	pAnim = GlobTomb4.pBaseAnimations;

	for (i=0;i<pAnim->TotAnimazioni;i++) {
		if (pAnim->VetAnimations[i].Flags & FAN_DISABLE_PUSH_AWAY) {
			pBase->VetAnimNumber[pBase->TotDisable]=pAnim->VetAnimations[i].AnimIndex;
			pBase->TotDisable++;
		}
	}

}

int ChiamaDefDlgProc(HWND hDlg, UINT Msg, WPARAM wParam, LPARAM lParam )
{
	return DefDlgProc(hDlg, Msg, wParam, lParam);
}

// chiamata all'uscite di finestra setup
// bisogna leggere i controlli delle mie setting e salvare il valore nel registro di windows
DWORD AggiornaMieChiaviRegistro(HWND hDlg)
{
	HWND WindRadio;
	int Value;

	WindRadio = GetDlgItem(hDlg, ID_SETUP_DISABLED);
	Value= SendMessage(WindRadio, BM_GETSTATE, 0,0);
	if (Value == BST_CHECKED) GlobTomb4.EmergencySettings= ES_DISABLED;

	WindRadio = GetDlgItem(hDlg, ID_SETUP_SOFT_FULL_SCREEN);
	Value= SendMessage(WindRadio, BM_GETSTATE, 0,0);
	if (Value == BST_CHECKED) GlobTomb4.EmergencySettings= ES_SOFT_FULL_SCREEN;

	WindRadio = GetDlgItem(hDlg, ID_SETUP_NO_WAITING_REFRESH);
	Value= SendMessage(WindRadio, BM_GETSTATE, 0,0);
	if (Value == BST_CHECKED) GlobTomb4.EmergencySettings= ES_NO_WAITING_REFRESH;

	return GlobTomb4.EmergencySettings;

}

// possibili valori da restituire
// #define RET_ABORT_FALSE 0x80000000
// #define RET_ABORT_TRUE  0x80000001
// #define RET_DEF_WINDOWPROC 0x0
// #define RET_CONTINUE 0x1

//#define ID_SETUP_DISABLED 1050
//#define ID_SETUP_SOFT_FULL_SCREEN 1051
//#define ID_SETUP_NO_WAITING_REFRESH 1052
DWORD RedirWindowProcSetup(HWND hDlg, UINT Msg, WPARAM wParam, LPARAM lParam)
{
	
	switch (Msg) {
	case WM_COMMAND:
		switch (LOWORD(wParam)) {
		case ID_SETUP_DISABLED:
			CheckRadioButton(hDlg, ID_SETUP_DISABLED, ID_SETUP_NO_WAITING_REFRESH, ID_SETUP_DISABLED);

			return RET_ABORT_FALSE;
		case ID_SETUP_SOFT_FULL_SCREEN:
			CheckRadioButton(hDlg, ID_SETUP_DISABLED, ID_SETUP_NO_WAITING_REFRESH, ID_SETUP_SOFT_FULL_SCREEN);
			return RET_ABORT_FALSE;

		case ID_SETUP_NO_WAITING_REFRESH:
			CheckRadioButton(hDlg, ID_SETUP_DISABLED, ID_SETUP_NO_WAITING_REFRESH, ID_SETUP_NO_WAITING_REFRESH);
			return RET_ABORT_FALSE;
		}
	}
	return RET_CONTINUE;
}
// chiamata una sola volta (INIT_DIALOG) quando si crea finestra setup
// inizializza i controlli della finestra setup ai valori effettivi del registro
void InitControlliSetup(HWND hWind)
{
	static int *pSetting_DD = (int *) 0x753898;
	static int *pSetting_D3D = (int *) 0x75389C;
	static int *Setting_VMode = (int *) 0x7538A0;
	static int *pSetting_TFormat = (int *) 0x7538A4;
	static int *pSetting_DS = (int *) 0x7538AC;
	DWORD ID_Now;
	static BYTE *pSetting_BumpMap = (BYTE*) 0x753936;
	int *pSetting_TextLow = (int*) 0x753937;
	int *pSetting_BumpLow = (int*) 0x75393B;
	static BYTE *pSetting_MMX_Funzioni = (BYTE*) 0x75393F;
	static BYTE *pSetting_Filter = (BYTE *) 0x753940;
	static BYTE *pSetting_Volumetric = (BYTE *) 0x753941;
	static BYTE *pSetting_DisableSound = (BYTE*) 0x753942;
	static BYTE *pSetting_NoFMV = (BYTE*) 0x4BFD59;
	static WORD *pSetting_FiltroBilineare = (WORD*) 0x4B040A;
	static int *pFlagsSettingRegistro = (int *) 0x753943;
	bool TestForced;

	HWND WindControl;

	WindControl=GetDlgItem(hWind, ID_SETUP_COMBO_SETTING_DD);
	SendMessage(WindControl, CB_SETCURSEL, (WPARAM) *pSetting_DD,0);


	WindControl=GetDlgItem(hWind, ID_SETUP_COMBO_SETTTING_D3D);
	SendMessage(WindControl, CB_SETCURSEL, (WPARAM) *pSetting_D3D,0);

	WindControl=GetDlgItem(hWind, ID_SETUP_COMBO_VIDEO_MODE);
	SelezionaComboValore(WindControl, *Setting_VMode);


	WindControl=GetDlgItem(hWind, ID_SETUP_COMBO_TIPO_TEX);
	SendMessage(WindControl, CB_SETCURSEL, (WPARAM) *pSetting_TFormat,0);

	WindControl=GetDlgItem(hWind, ID_SETUP_COMBO_AUDIO_DEVICES);
	SendMessage(WindControl, CB_SETCURSEL, (WPARAM) *pSetting_DS,0);


	if (*pSetting_DisableSound) {
		CheckDlgButton(hWind, ID_SETUP_CHECK_DISATTIVA_AUDIO, BST_CHECKED);
	}else {
		CheckDlgButton(hWind, ID_SETUP_CHECK_DISATTIVA_AUDIO, BST_UNCHECKED);
	}

	if (*pSetting_Volumetric) {
		CheckDlgButton(hWind, ID_SETUP_CHECK_VOLUMETRIC, BST_CHECKED);
	}else {
		CheckDlgButton(hWind, ID_SETUP_CHECK_VOLUMETRIC, BST_UNCHECKED);
	}

	if (*pSetting_Filter) {
		CheckDlgButton(hWind, ID_SETUP_CHECK_BILINEAR, BST_CHECKED);
	}else {
		CheckDlgButton(hWind, ID_SETUP_CHECK_BILINEAR, BST_UNCHECKED);
	}

	if (*pSetting_BumpMap) {
		CheckDlgButton(hWind, ID_SETUP_CHECK_BUMP_MAP, BST_CHECKED);
	}else {
		CheckDlgButton(hWind, ID_SETUP_CHECK_BUMP_MAP, BST_UNCHECKED);
	}

	if (*pSetting_TextLow == 0x80) {
		CheckDlgButton(hWind, ID_SETUP_CHECK_LOW_TEX, BST_CHECKED);
	}else {
		CheckDlgButton(hWind, ID_SETUP_CHECK_LOW_TEX, BST_UNCHECKED);
	}

	if (*pSetting_BumpLow == 0x80) {
		CheckDlgButton(hWind, ID_SETUP_CHECK_LOW_BUMP, BST_CHECKED);
	}else {
		CheckDlgButton(hWind, ID_SETUP_CHECK_LOW_BUMP, BST_UNCHECKED);
	}

	if (*pSetting_NoFMV) {
		CheckDlgButton(hWind, ID_SETUP_CHECK_DISABLE_FMV, BST_CHECKED);
	}else {
		CheckDlgButton(hWind, ID_SETUP_CHECK_DISABLE_FMV, BST_UNCHECKED);
	}

	if ((*pFlagsSettingRegistro & 0x90) == 0x90) {
		CheckRadioButton (hWind, ID_SETUP_RADIO_HARDWARE, ID_SETUP_RADIO_SOFTWARE, ID_SETUP_RADIO_HARDWARE);
	}else {
		CheckRadioButton (hWind, ID_SETUP_RADIO_HARDWARE, ID_SETUP_RADIO_SOFTWARE, ID_SETUP_RADIO_SOFTWARE);
	}

	if (*pFlagsSettingRegistro & 0x02) {
		CheckDlgButton(hWind, ID_SETUP_CHECK_WINDOWED, BST_CHECKED);
	}else {
		CheckDlgButton(hWind, ID_SETUP_CHECK_WINDOWED, BST_UNCHECKED);
	}

	// se ci sono impostazioni di script forzare quei valori
	TestForced=false;
	if (GlobTomb4.Settings & SET_FORCE_SOFT_FULL_SCREEN) {
		GlobTomb4.EmergencySettings = ES_SOFT_FULL_SCREEN;
		TestForced=true;
	}else {
		if (GlobTomb4.Settings & SET_FORCE_NO_WAITING_REFRESH) {
			GlobTomb4.EmergencySettings = ES_NO_WAITING_REFRESH;
			TestForced=true;
		}
	}

	switch (GlobTomb4.EmergencySettings) {
	case ES_DISABLED:
		ID_Now= ID_SETUP_DISABLED;
		break;
	case ES_SOFT_FULL_SCREEN:	
		ID_Now= ID_SETUP_SOFT_FULL_SCREEN;
		break;
	case ES_NO_WAITING_REFRESH:
		ID_Now= ID_SETUP_NO_WAITING_REFRESH;
		break;
	}

	CheckRadioButton (hWind, ID_SETUP_DISABLED, ID_SETUP_NO_WAITING_REFRESH, ID_Now);
	// ora disattivarlo in modo che non possa essere modificato
	if (TestForced) {
		WindControl=GetDlgItem(hWind, ID_SETUP_DISABLED);
		EnableWindow(WindControl, FALSE);

		WindControl=GetDlgItem(hWind, ID_SETUP_SOFT_FULL_SCREEN);
		EnableWindow(WindControl, FALSE);

		WindControl=GetDlgItem(hWind, ID_SETUP_NO_WAITING_REFRESH);
		EnableWindow(WindControl, FALSE);
	}
}

// salva i parametri di input della funzione doslider, per poterla poi richiamare DOPO
// aver visualizzato l'immagine title di background custom
void SalvaInputSlider(DWORD *pVetStack)
{
	SalvaSliderInput *pSlider;
	int i;

	// analizzando pVetStack[0] posso scoprire da dove e stato chiamata
	switch (pVetStack[0]) {
	case 0x47A38D:
		// music
		pSlider= &GlobTomb4.SliderMusic;
		break;
	case 0x47A3CB:
		// sfx
		pSlider=&GlobTomb4.SliderSfx;
		break;
	default:
		return;
	}

	pSlider->TestUsed=true;

	for (i=0;i<8;i++) {
		pSlider->Parameters[i] = pVetStack[i+1];
	}

}

void AggiornaPosizioneDardo(StrItemTr4 *pItem)
{

	int IncX, IncZ;

	CalcolaIncremento(pItem->OrientationH, &IncX, &IncZ, pItem->SpeedH);

	// salvare posizione immediatamente precedente
	DardoOldX= pItem->CordX;
	DardoOldZ= pItem->CordZ;

	pItem->CordX += IncX;
	pItem->CordZ += IncZ;

}

DWORD ItemBloccaPushable(StrItemTr4 *pItem) 
{
	// scoprie se lo slot di questo item ha flag FFS_PUSHABLE_CAN_OVERSTEP_IT
	int i;
	StrCustSlotFlag *pFlag;

	pFlag = &GlobTomb4.pBaseCustomize->BaseSlotFlags.VetSlotFlags[0];

	for (i=0;i<GlobTomb4.pBaseCustomize->BaseSlotFlags.TotSlotFlags;i++) {
		if (pFlag->Slot == pItem->SlotID  && (pFlag->Flags & FFS_PUSHABLE_CAN_OVERSTEP_IT)) {
			return 0;
		}
		pFlag++;
	}
	return 1;
	
}
// se chiamato dopo caricamento savegame bisogna impostare TestClear=false, perche'bisogna mantenere
