// il savegame (se presente) e' gia' stato caricato, tutti i valori impostati, incluse camera
void LastFirstGameCycle(void)
{
	CreaCollisioniPushable();
}
// esegue callback first e after di slot per procedura floor
int EseguiCB_SLotFloorCeiling(int CB_Value, int CBT_Flags, StrItemTr4 *pItem, 
							DWORD CordX, int CordY, DWORD CordZ, int *pNewY)
{
	DWORD i;
	StrMyDatabase *pDB;
	StrPluginRec *pRec;
	StrRecordCallBack *pCall;
	int j;
	int SlotNow;
	int RetValue;
	int Temp;
	CALL_SLOT_CB_FLOOR MyCall;

	RetValue = SRET_OK;

	SlotNow = pItem->SlotID;
	pDB = &MyGlobPrivate.DataBase;

	pRec = &pDB->pVetPlugins[1];

	for (i=1;i<pDB->TotPlugins-1;i++) {
		pCall = &pRec->VetRequiredCB[0];
		for (j=0;j<pRec->TotRequiredCB;j++) {
			if (pCall->CB_Tipo == CB_Value &&
				(pCall->Flags & CBT_Flags) !=0 && 
				pCall->Numero == SlotNow) {
				MyCall = (CALL_SLOT_CB_FLOOR) pCall->pCall;
				// (WORD CBT_Flags, StrItemTr4 *pItem, DWORD CordX, int CordY, DWORD CordZ, int *pNewCordY);
				Temp = MyCall(CBT_Flags, pItem, CordX, CordY, CordZ, pNewY);
				if (Temp != 0) {
					RetValue |= Temp;
				}
			}
			pCall++;
		}
		pRec++;
	}

	return RetValue;
}
// esegui callback first e after per  CB_STATE_ID_LARA_CTRL o CB_STATE_ID_LARA_COLLISION
int EseguiCB_StateIdFirstAfter(int CB_Value, WORD CBT_Flags, StrItemTr4 *pLara, StrCollisionLara *pColl)
{
	CALL_CB_STATE_ID MyCall;
	DWORD i;
	int j;
	StrMyDatabase *pDB;
	StrPluginRec *pRec;
	StrRecordCallBack *pCall;
	int RetValue;
	int Temp;
	WORD StateIdNow;

	RetValue = SRET_OK;
	StateIdNow = pLara->StateIdCurrent;

	pDB = &MyGlobPrivate.DataBase;

	pRec = &pDB->pVetPlugins[1];

	for (i=1;i<pDB->TotPlugins;i++) {
		pCall = &pRec->VetRequiredCB[0];
		for (j=0;j<pRec->TotRequiredCB;j++) {
			if (pCall->CB_Tipo == CB_Value &&
				(pCall->Flags & CBT_Flags) !=0 && 
				pCall->Numero == StateIdNow) {	

				// trovata:
				MyCall = (CALL_CB_STATE_ID) pCall->pCall;
				// (WORD StateId, WORD CBT_Type, StrItemTr4 *pLara, StrCollisionLara * pCollision);
				Temp = MyCall(StateIdNow, CBT_Flags, pLara, pColl);
				if (Temp != SRET_OK) {
					RetValue |= Temp;
				}

			}
			pCall++;

		}
		pRec++;
	}

	return RetValue;
}
int EseguiCB_SlotFirstAfter(int CB_Value, short ItemIndex, StrItemTr4 *pItem, int CB_Flags, StrCollisionLara *pColl)
{

	// eseguire tutte le patch del tipo di input nella sequenza dei plugin
	// funziona per: CB_SLOT_INITIALISE ; CB_SLOT_CONTROL e CB_SLOT_COLLISION e CB_SLOT_DRAW
	DWORD i;
	StrMyDatabase *pDB;
	StrPluginRec *pRec;
	StrRecordCallBack *pCall;
	int j;
	int SlotNow;
	int RetValue;
	CALL_SLOT_MANY MyCall;
	CALL_SLOT_CB_COLLISION MyCallCollision;

	int Temp;

	RetValue = SRET_OK;

	SlotNow = pItem->SlotID;
	pDB = &MyGlobPrivate.DataBase;

	pRec = &pDB->pVetPlugins[1];

	for (i=1;i<pDB->TotPlugins;i++) {
		pCall = &pRec->VetRequiredCB[0];
		for (j=0;j<pRec->TotRequiredCB;j++) {
			if (pCall->CB_Tipo == CB_Value &&
				(pCall->Flags & CB_Flags) !=0 && 
				pCall->Numero == SlotNow) {

				// trovata call back di stesso tipo e numero: eseguirla
				switch (CB_Value) {
				case CB_SLOT_INITIALISE:
				case CB_SLOT_CONTROL:
				case CB_SLOT_DRAW:
				case CB_SLOT_DRAW_EXTRA:

					MyCall = (CALL_SLOT_MANY) pCall->pCall;
					Temp = MyCall(ItemIndex, pItem, CB_Flags);
					break;
				case CB_SLOT_COLLISION:
					MyCallCollision = (CALL_SLOT_CB_COLLISION) pCall->pCall;
					//(short IndexItem, StrItemTr4 *pItem, WORD CBT_Flags, StrCollisionLara * pCollision);
					Temp = MyCallCollision(ItemIndex, pItem, CB_Flags,  pColl);
					break;

				}
				if (Temp != SRET_OK) {
					RetValue |= Temp;
				}

			}
			pCall++;

		}
		pRec++;
	}

	return RetValue;

}

// complicatissima funzione per trovare callback a trng patch
// se viene trovata una callback di tipo asm allora esce subito e imposta in pGoAsmCallback l'indirizzo a dove
// saltare.
// se invece trova una callback in c la esegue subito ed eventualmente in sequenza
// quando esce, e non ci sono valori validi in pGoAsmCallback (NULL) vuol dire che ha terminato
// se quando viene chiamata ci sono valori diversi da -1 per pIndexStartPlugin
// vuol dire che si sta proseguendo un ciclo precedente nel qual caso bisogna incrmeentare la callback
// e andare avanti
// e' di tipo CBT_FIRST or CBT_AFTER
void AnalisiCB_TrngPatches(WORD IndicePatch, WORD CBT_Type, bool TestJumpPatch, 
						   DWORD *pIndexStartPlugin, DWORD *pIndexStartCall,
						  void **pGoAsmCallback, StrRegisters *pRegistri)
{
	DWORD IndicePlugin;
	DWORD IndiceCall;
	StrMyDatabase *pDB;
	StrPluginRec *pRec;
	StrRecordCallBack *pCall;
	bool TestContinua;
	CALL_CB_NUMERIC_TRNG_PATCH MyCall;


	pDB = &MyGlobPrivate.DataBase;

	IndicePlugin = *pIndexStartPlugin;
	IndiceCall = *pIndexStartCall;
	if (IndicePlugin == -1) {
		// siamo alla prima esecuzione
		TestContinua=false;
		pRec = &pDB->pVetPlugins[1];
		IndicePlugin=1;
		IndiceCall =0;

	}else {
		// stiamo continuando da un precedente ciclo
		TestContinua=true;
		pRec = &pDB->pVetPlugins[IndicePlugin];
		IndiceCall++;

	}
	
	while (IndicePlugin < pDB->TotPlugins) {
		pCall = &pRec->VetRequiredCB[IndiceCall];
		while (IndiceCall < (DWORD) pRec->TotRequiredCB) {

			if (pCall->CB_Tipo == CB_NUMERIC_TRNG_PATCH &&
				pCall->Numero == IndicePatch &&
				(pCall->Flags & CBT_Type)	!= 0) {

				// trovata una patch
				// agire in modo molto diverso a seconda se e' di tipo asm o di tipo c++
				if (pCall->Flags & CBT_ASM) {
					// ora si deve impostare l'indirizzo e poi uscire salvando indiceplugin e call attuali
					*pGoAsmCallback = pCall->pCall ;
					*pIndexStartPlugin = IndicePlugin;
					*pIndexStartCall = IndiceCall;
					return;
				}
				// e' di tipo C
				// passare i valori alla callback
				MyCall = (CALL_CB_NUMERIC_TRNG_PATCH) pCall->pCall;
				// (WINAPI *CALL_CB_NUMERIC_TRNG_PATCH) (WORD PatchIndex, WORD CBT_Flags, bool TestFromJump, StrRegisters *pRegisters);
				MyCall(IndicePatch, CBT_Type, TestJumpPatch, pRegistri);

				return;
			}
			IndiceCall++;
			pCall++;
		}
		IndicePlugin++;
		IndiceCall=0;
		pRec++;
	}

}

