void StopSuWalk(void)
{
	StrCollisionLara *pColl;
	StrItemTr4 *pLara;

	pColl = GlobTomb4.pAdr->pCollisionLara;


	if (pColl->StateIdOld == 0 && pColl->AnimNowOld == 1){
		EseguiAnimazione( 3,0,true);
		return;
	}

	if (pColl->AnimNowOld == 20) {
		EseguiAnimazione( 103,0, true); 
		return;
	}

	pLara = GlobTomb4.pAdr->pLara;
	pLara->StateIdCurrent= pColl->StateIdOld;
	pLara->AnimationNow = pColl->AnimNowOld;
	pLara->FrameNow = pColl->FrameNowOld;
	return;
	
}
